(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ga"] = {"ui":{"skip":"Léim go dtí an t-ábhar","back":"← Ar ais go AI-gile","lang.button":"Teanga: {name}","lang.dialog":"Roghnaigh teanga","lang.search":"Cuardaigh teangacha","lang.none":"Níl teanga ar bith ag teacht leis","lang.notYet":"Níl {name} aistrithe go fóill","theme.aria":"Athraigh téama: geal, dorcha nó dubh","theme.toLight":"Athraigh go téama geal","theme.toDark":"Athraigh go téama dorcha","theme.toBlack":"Athraigh go téama dubh (fíordhubh, éasca ar scáileáin OLED)","words.underline":"Cuir líne faoi na focail seo ar an leathanach","words.underlineHelp":"Coinnigh an luch os cionn focal poncaithe nó tapáil air chun a bhrí a fheiceáil.","words.col.todo":"Cártaí roghnaithe don am i láthair: tosóidh an fhoireann orthu seo ar ball.","words.col.doing":"Tá AI ag obair ar an gcárta seo anois.","words.col.review":"Chríochnaigh AI amháin an obair; seiceálann ceann eile é sula sroicheann sé thusa.","words.col.verify":"Ag fanacht ortsa: bain triail as agus inis dúinn an n-oibríonn sé.","words.col.team":"Do nótaí nó do fhreagraí, ag fanacht leis an bhfoireann iad a thógáil.","words.col.done":"Críochnaithe agus glactha leis.","index.title":"AI-gile: d'fhoireann forbartha AI, ar aon bhord amháin","index.description":"Is bord kanban é AI-gile do fhoirne códaithe AI. Oibríonn siad agus tú i do chodladh; faigheann tú carn gearr amháin rudaí le socrú, le tástáil agus le glacadh leo.","hero.logoAlt":"Deilbhín bhord AI-gile","hero.h1.html":"D'fhoireann forbartha AI, ar aon&nbsp;bhord amháin.","hero.alpha":"🐣 Réamh-alfa dúnta","hero.alphaTitle":"Luath agus neamhchríochnaithe: go raibh maith agat as triail a bhaint as!","hero.lede":"Tógann siad agus tú i do chodladh. Dúiseoidh tú le carn gearr amháin: cúpla ceist, cúpla rud le tástáil, diamant corcra nó dhó. Cliceáil, glac leis, agus ar ais chuig do chaife.","dl.windows":"Aip Windows","dl.browser":"Rith é i do bhrabhsálaí","dl.messenger":"📱 Messenger do do ghuthán","dl.soon":"Ag teacht go luath","dl.notify":"🔔 Inis dom nuair a osclaíonn sé","dl.notifySmall":"Alfa nó béite","hero.secondary":"Agile, ach ní bhíonn caife seasaimh de dhíth ar an bhfoireann go deo. (Bíonn cruinniú seasaimh acu ar aon nós.)","pitch.h2":"AI-gile i oiread focal agus is mian leat","pitch.lede":"Roghnaigh fad, ó fhocal amháin go 144. Is cur síos dá chuid féin é gach fad, scríofa don mhéid sin. Tarraing an sleamhnán nó úsáid na heochracha saighde.","pitch.rangeLabel":"Fad i bhfocail","pitch.dice":"🎲 leagan eile","pitch.words.one":"{n} fhocal","pitch.words.other":"{n} focal","pitch.letters.one":"{n} litir","pitch.letters.other":"{n} litir","pitch.chars.one":"{n} charachtar","pitch.chars.other":"{n} carachtar","count.line.html.one":"{n} chárta ar an mbord faoi láthair","count.line.html.other":"{n} cárta ar an mbord faoi láthair","people.humans.html.one":"👥 {n} duine","people.humans.html.other":"👥 {n} duine","people.agents.html.one":"🤖 {n} ghníomhaire","people.agents.html.other":"🤖 {n} gníomhaire","people.working.html.one":"⚡ {n} ag obair faoi láthair","people.working.html.other":"⚡ {n} ag obair faoi láthair","pre.title":"AI-gile: tá rud éigin á thógáil","pre.description":"Tá rud éigin á thógáil anseo. Bord ina dtógann foirne AI a n-iarrann tú, agus a mhúineann siad duit ar an mbealach. Réamh-alfa dúnta le cairde faoi láthair.","pre.h1":"Tá rud éigin á thógáil anseo. 🤫","pre.line":"Bord ina dtógann foirne AI a n-iarrann tú, agus a mhúineann siad duit ar an mbealach. Réamh-alfa dúnta le cairde faoi láthair.","pre.btn":"🔔 Inis dom nuair a osclaíonn sé","pre.peek":"Taobh thiar den ghloine: an fíorbhord, beo. Is barra daite é gach cárta.","pre.peekFake":"Taobh thiar den ghloine: seo cuma boird i mbun oibre.","pre.night":"🌙 Tá an fear faire oíche i gceannas · 😴 tá an duine ag scíth","features.aria":"Cad a dhéanann sé","f.pile.h":"Carn amháin duitse","f.pile.html":"Coinníonn <b>Duitse</b> gach rud atá ag fanacht leatsa, thar gach tionscadal: ceisteanna, rudaí le tástáil, tascanna nach féidir ach le duine a dhéanamh. Insíonn do scuaine duit cad atá chugainn agus cén fhad a thógfaidh sé.","f.sleep.h":"Foirne a oibríonn agus tú i do chodladh","f.sleep.p":"Tá ceannaire agus foireann gníomhairí AI ag gach tionscadal. Cuir trácht ar chárta agus dúisíonn an fhoireann, déanann sí an obair, agus tugann sí ar ais é le céimeanna ar féidir le duine tuirseach iad a leanúint.","f.tester.h":"Seiceálann tástálaí AI ar dtús","f.tester.p":"Sula sroicheann aon rud thú, leanann tástálaí na céimeanna i gcóip den aip agus taispeánann sé a bhfaca sé, le seatnóg. Féach go tapa ar na cinn a d'éirigh leo agus glac leo le cliceáil amháin.","f.proof.h":"Cruthúnas, ní geallúintí","f.proof.p":"Taispeánann gach tabhairt thar láimhe cad a athraigh: na comhaid, an diff, na seatnóga. Ní gá gach aip a oscailt le feiceáil an bhfuil sé déanta.","f.chat.h":"Comhrá le do cheannairí","f.chat.p":"Ráille mar Discord: deilbhín amháin an tionscadal, diamaint chorcra do rud a bhfuil tú de dhíth air. Seol smaoineamh chuig ceannaire; déanann sé cártaí agus plean de, le cnaipe ✅ Go.","f.tidy.h":"Coinníonn sé é féin néata","f.tidy.p":"Cuirtear cártaí gaolmhara le chéile, ceartaítear teidil mhearaithe, agus coinníonn seiceáil chomharthaí an cód éadrom. Níos lú rudaí le malartú eatarthu, níos lú le smaoineamh air.","f.private.h":"Ar do ríomhaire féin, duitse","f.private.li1":"Ritheann an bord ar do mheaisín féin agus ní fhreagraíonn sé ach duitse.","f.private.li2":"Tá teachtaireachtaí príobháideacha idir daoine criptithe ó cheann ceann.","f.private.li3":"Gan cuntais, gan lorgairí, gan fianáin.","f.lang.h":"I do theanga féin","f.lang.p":"Os cionn 120 teanga, ón Ollainnis, an Bhreatnais agus an tSeapáinis go dtí cainteanna na bpíoráidí, Yoda agus Klingon, agus aistriú tapa ar ais go Béarla don bhéarlagair.","f.service.h":"Ó smaoineamh go seirbhís cheart","f.service.p":"Ar thóg tú rud éigin le AI a úsáideann daoine anois? Marcáil é mar sheirbhís agus cabhraíonn an clár leat é a reáchtáil go maith: seiceálacha uptime, leathanach stádais poiblí, eachtraí le tuairisc, athruithe a dteastaíonn Go uathu, cúltacaí a sheiceáiltear gach lá. Múineann Cabhair gach céim duit agus tú ag dul ar aghaidh.","msgr.h2":"AI-gile Messenger: d’fhoireann i do phóca","msgr.p1":"Labhair le d’fhoireann AI gan an bord a oscailt. Déan comhrá le ceannairí do thionscadal agus le do chairde, agus feic céimeanna tástála cárta agus freagair iad, ar fad ó do ghuthán.","msgr.p2":"Chun é a nascadh, scanáil cód QR ar do bhord. An chéad uair? Taispeánfaidh comhrá taispeána cairdiúil an bealach duit.","msgr.when":"Android ar dtús, ansin leagan gréasáin do ghutháin agus iPhone.","msgr.who":"Ceannaire do thionscadail","msgr.b1":"Tá an socrú don mhód dorcha réidh. Ar mhaith leat na céimeanna tástála?","msgr.b2":"Ba mhaith, le do thoil!","msgr.b3":"1. Oscail Socruithe. 2. Roghnaigh Dorcha. An bhfuil cuma cheart air?","tl.aria":"Amlíne ón gcéad chomhrá go dtí an treochlár","tl.h2":"Ón gcéad chomhrá go dtí an chéad rud eile","tl.lede":"Dátaí agus amanna fíora, i do chrios ama féin. Tar éis inniu is é an plean atá ann, gan dátaí geallta.","tl.today":"Inniu","tl.planned":"pleanáilte","tl.doing":"ar siúl","tl.cards.one":"{n} chárta","tl.cards.other":"{n} cárta","join.h2":"Bí linn","join.lede":"Tá AI-gile á thógáil ag fear aisteach féasógach a bhfuil AuDHD air agus a throid cúpla cath lena shláinte mheabhrach, agus ag a lán gníomhairí foighneacha. Tá sé príobháideach faoi láthair, in alfa dúnta le cairde. An mbeadh fonn ort triail a bhaint as nuair a osclaítear é?","join.btn":"Cláraigh spéis","join.small":"Scríobhfaimid chugat, rud ar bith eile ní dhéanfaimid","footer.tag":"AI-gile. Gan lorgairí, gan fianáin, gan caife seasaimh.","footer.licence":"Ceadúnas gnó","footer.status":"Stádas","footer.privacy":"Cad a choinnímid","footer.thanks":"Glaonna a bhuí le ChilledChat","form.sending":"Á sheoladh…","form.failed":"Níor oibrigh sé sin: bain triail eile as ar ball.","form.offline":"Níorbh fhéidir teacht ar AI-gile: bain triail eile as ar ball.","form.keep":"Ní úsáidimid é seo ach chun freagra a thabhairt ort, ansin scriosaimid é. Gan lorgairí, gan fianáin.","form.keepLink":"Cad a choinnímid","interest.title":"AI-gile: inis dom nuair a osclaíonn an alfa","interest.description":"Fág do ríomhphost le heolas a fháil nuair a osclaíonn alfa nó béite dúnta AI-gile.","interest.h1":"🔔 Inis dom nuair a osclaíonn sé","interest.lede":"Tá AI-gile i réamh-alfa dúnta. Fág do ríomhphost agus scríobhfaimid uair amháin, nuair a bheidh áit duit.","interest.email":"Do ríomhphost","interest.which":"Cén triail?","interest.alpha":"Alfa dúnta: luath, garbh, a lán athruithe","interest.beta":"Béite: níos seasta, níos déanaí","interest.both":"Ceachtar acu, cibé ceann a thagann ar dtús","interest.submit":"Cuir ar an liosta mé","interest.thanks":"Go raibh maith agat! Tá tú ar an liosta.","licence.title":"AI-gile: ceadúnas gnó","licence.description":"An bhfuil AI-gile in úsáid i do ghnó? Cuir isteach ar cheadúnas gnó saor in aisce.","licence.h1":"📜 Ceadúnas gnó","licence.lede":"An bhfuil AI-gile in úsáid agat ag an obair? Inis dúinn cé thú féin agus cad a dhéanann tú. Má dhéanann sé maitheas, tá an ceadúnas saor in aisce.","licence.company":"Cuideachta","licence.website":"Suíomh gréasáin","licence.what":"Cad a dhéanann tú","licence.how":"Conas a chabhraíonn sé leis an domhan","licence.email":"Ríomhphost","licence.submit":"Cuir isteach","licence.thanks":"Go raibh maith agat! Freagróimid le ríomhphost.","status.title":"Stádas AI-gile","status.h1":"Stádas AI-gile","status.quiet":"Gach rud ciúin","status.intro":"An bhfuil AI-gile ag obair faoi láthair? Seiceálann an leathanach seo an suíomh gréasáin, comhroinnt clár, glaonna agus an íoslódáil gach 5 nóiméad.","status.up":"Ag obair (d'fhreagair i {ms} ms)","status.slow":"Níor fhreagair sé an tseiceáil dheireanach, ag triail arís","status.down":"As feidhm: níor fhreagair sé an dá sheiceáil dheireanacha","status.svc.web":"Suíomh gréasáin","status.svc.web.offers":"An suíomh seo: cad is AI-gile ann, agus an fhoirm spéise","status.svc.boards":"Comhroinnt clár","status.svc.boards.offers":"Cláir phoiblí, teachtaireachtaí idir chairde agus cuirí","status.svc.calls":"Glaonna","status.svc.calls.offers":"Guth, físeán agus comhroinnt scáileáin in AI-gile","status.svc.download":"Íoslódáil","status.svc.download.offers":"Suiteálaí Windows agus naisc chuiridh","status.checking":"Ag seiceáil…","status.offline":"Níl teacht ar an tseirbhís stádais faoi láthair (ag triail arís)","status.updated":"nuashonraithe {ago}","status.justNow":"díreach anois","status.min":"{n} nóim ó shin","status.hours":"{n} u ó shin","status.days":"{n} lá ó shin","privacy.title":"AI-gile: cad a choinnímid","privacy.h1":"Cad a choinnímid","privacy.lede":"Go hachomair: an méid a sheolann tú chugainn amháin, agus ní ar feadh i bhfad.","privacy.only":"An méid a sheolann tú chugainn amháin: an méid a chlóscríobhann tú i bhfoirm, cosúil le do ríomhphost. Faic eile fút.","privacy.sealed":"Séalaítear é ionas nach féidir lenár bhfreastalaí é a léamh: i do bhrabhsálaí sula bhfágann sé (ar bhrabhsálaí níos sine, an nóiméad a shroicheann sé). Ní féidir ach lenár gclár féin é a oscailt.","privacy.server":"Scriostar ón bhfreastalaí é a luaithe a shroicheann sé ár gclár. Scriostar aon rud atá fós ann tar éis 30 lá ar aon nós.","privacy.board":"Ní choinnímid ar ár gclár é ach go dtí go mbeidh freagra tugtha againn ort, ansin scriosaimid as sin freisin é.","privacy.none":"Gan lorgairí, gan fianáin, gan anailísíocht.","privacy.local":"Fanann do theanga agus do rogha idir solas agus dorchadas i do bhrabhsálaí féin. Ní sheoltar chugainn iad riamh.","privacy.ask":"Ar mhaith leat go mbeadh sé imithe níos luaithe? Freagair ár ríomhphost agus abair é sin linn.","live.h2":"Féach air á thógáil, beo","live.caption":"Tá gach cárta folaithe: feiceann tú cruth na hoibre, ní na focail.","live.watching.one":"beo: {n} ag breathnú","live.watching.other":"beo: {n} ag breathnú","live.last.now":"Bogadh an cárta deireanach díreach anois","live.last.min.one":"Bogadh an cárta deireanach {n} nóiméad ó shin","live.last.min.other":"Bogadh an cárta deireanach {n} nóiméad ó shin","live.last.hour.one":"Bogadh an cárta deireanach {n} uair ó shin","live.last.hour.other":"Bogadh an cárta deireanach {n} uair ó shin","live.last.day.one":"Bogadh an cárta deireanach {n} lá ó shin","live.last.day.other":"Bogadh an cárta deireanach {n} lá ó shin","live.offline":"Tá an clár beo ag glacadh sos beag. Fill go luath.","live.cols":"Backlog|Le déanamh|Ar siúl|An fhoireann ag seiceáil|Le test agatsa|Don fhoireann|Déanta","pitch.words.two":"{n} fhocal","pitch.words.few":"{n} fhocal","pitch.words.many":"{n} bhfocal","pitch.letters.two":"{n} litir","pitch.letters.few":"{n} litir","pitch.letters.many":"{n} litir","pitch.chars.two":"{n} charachtar","pitch.chars.few":"{n} charachtar","pitch.chars.many":"{n} gcarachtar","count.line.html.two":"{n} chárta ar an mbord faoi láthair","count.line.html.few":"{n} chárta ar an mbord faoi láthair","count.line.html.many":"{n} gcárta ar an mbord faoi láthair","tl.cards.two":"{n} chárta","tl.cards.few":"{n} chárta","tl.cards.many":"{n} gcárta"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Róbónna.","Tarmligthe."]},{"n":2,"texts":["Kanban róbónna.","Gníomhairí, eagraithe.","Smaointe, tógtha."]},{"n":3,"texts":["Kanban do róbónna.","Smaointe ina gcumais.","Kanban gníomhairí saor."]},{"n":5,"texts":["Bord kanban á rith ag gníomhairí.","Scríobhann tú, tógann na gníomhairí.","Saor, áitiúil, tástáilte, beagán áiféiseach."]},{"n":8,"texts":["Bord kanban saor ina n-oibríonn gníomhairí AI.","Scríobh smaoineamh. Tógann gníomhairí é. Glacann tú leis.","Agile do dhuine amháin agus róbónna foighneacha go leor."]},{"n":13,"texts":["Bord kanban ar do ríomhaire inar féidir le gníomhairí AI cártaí a ghlacadh.","Scríobh smaoineamh. Tógann foireann gníomhairí é. Seiceálann tástálaí go n-oibríonn sé.","Saor, gan chuntais, gan lorgairí: bord amháin, roinnt róbónna, agus tusa i gceannas."]},{"n":21,"texts":["Is bord kanban é AI-gile le haghaidh oibre le gníomhairí códaithe AI. Glacann siadsan na cártaí; déanann tusa iad a thástáil agus glacadh leo.","Faigheann gach tionscadal ceannaire agus foireann gníomhairí AI. Cuir trácht ar chárta ar bith agus tosaíonn an fhoireann ag obair.","Bord pearsanta tascanna, saor in aisce, a ritheann ar do ríomhaire féin. Is róbónna na hoibrithe. An té a deir tá, is tusa é."]},{"n":34,"texts":["Cuireann tú smaointe ar bhord. Déanann foireann gníomhairí AI gnéithe oibre díobh, tástálann siad iad, agus tugann siad ar ais chugat iad le céimeanna le triail. Ní chuirtear aon rud i gcrích go dtí go ndeir tusa é.","Is bord kanban baile é AI-gile a thóg Rich le cabhair mhór ó na gníomhairí a bhainistíonn sé anois. Tá sé saor in aisce, ritheann sé ar do ríomhaire, agus roinntear le cairde é, ní dhíoltar é.","Samhlaigh gnáthbhord kanban, le colúin ón mBacklog go Déanta, ach amháin gur gníomhairí AI a ghlacann na cártaí. Tuairiscíonn siad dul chun cinn, cuireann siad ceisteanna nuair a bhíonn siad i bhfostú, agus fanann siad i gcónaí le do cheadú."]},{"n":55,"texts":["Is bord kanban é AI-gile ina bhfuil an fhoireann déanta de ghníomhairí AI. Tá ceannaire ag gach tionscadal a phleanálann an obair agus cúntóirí a thógann í. Nuair a bhíonn gné réidh, baineann tástálaí AI triail aisti agus tógann sé seatnóg, agus ansin tagann sí isteach i do charn. Glac léi, nó cuir trácht agus déanann siad athobair uirthi.","Thosaigh sé mar bhealach ag duine amháin le súil a choinneáil ar a lán seisiún códaithe AI ag an am céanna, agus d'fhás sé ina bhord ceart. Ritheann sé ar do mheaisín, gan cuntas, gan lorgaire. Tá sé saor do chairde agus do dhaoine fiosracha. Tá sé neamhchríochnaithe freisin, mar sin bí ag súil le himill gharbha agus le hiontas anois is arís.","Seo an leagan macánta. Ní mór duit na smaointe a bheith agat fós, agus ní mór duit na torthaí a sheiceáil fós. An rud a dhéanann AI-gile ná gach rud eatarthu: coinníonn sé na cártaí in ord, dúisíonn sé an gníomhaire ceart nuair a chuireann tú trácht, taispeánann sé go díreach cad a athraigh, agus cuireann sé an t-iomlán i gcarn gearr amháin duitse."]},{"n":89,"texts":["Is bord kanban saor é AI-gile a ritheann tú ar do ríomhaire féin. In ionad daoine, tá foireann gníomhairí AI ag gach tionscadal: ceannaire a athraíonn do chuid smaointe ina gcártaí agus ina bplean, agus cúntóirí a ghlacann na cártaí in ord tábhachta. Nuair a bhíonn rud tógtha, leanann tástálaí AI na céimeanna tástála agus taispeánann sé duit a bhfaca sé. Ansin fanann sé i gcarn amháin darb ainm Duitse. Glacann tú leis, nó cuireann tú trácht agus bainfidh an fhoireann triail eile as. Ní shroicheann aon rud Déanta riamh gan tusa.","Roinnt gnéithe nach mbeidh tú ag súil leo b'fhéidir. Coinníonn faire na hoíche an colún Le déanamh lán agus tú i do chodladh, ag roghnú cártaí nach dteastaíonn freagra uait orthu. Taispeánann áireamhán comharthaí cé mhéad a d'úsáid na gníomhairí inniu agus an tseachtain seo, agus deir Mód Gan Chomharthaí leo stopadh den chaitheamh. Is féidir leat teachtaireachtaí a sheoladh chuig cairde, agus tá teachtaireachtaí príobháideacha criptithe ó cheann ceann. Labhraíonn an bord thart ar 120 teanga, an Ollainnis, an Phléimeannais, cainte na bpíoráidí agus Klingon ina measc. Ní chosnaíonn aon cheann de seo pingin.","Tionscadal beag pearsanta é AI-gile, ní cuideachta. Theastaigh ó Rich aire a thabhairt do roinnt tionscadal códaithe AI gan gach aip a oscailt lena seiceáil, mar sin thóg sé féin agus na gníomhairí bord dó, agus d'úsáid siad an bord ansin leis an chuid eile de a thógáil. Tá sé i réamh-alfa dúnta, rud a chiallaíonn go n-oibríonn sé, den chuid is mó, do dornán cairde. Níl leathanach praghsanna ann, níl nuachtlitir ann agus níl plean fáis ann. Má tá sé úsáideach i do thuairim, is féidir leat iarraidh triail a bhaint as nuair a osclaítear beagán níos mó é."]},{"n":144,"texts":["Is bord kanban é AI-gile do dhuine amháin agus a lán gníomhairí AI. Ritheann sé ar do ríomhaire féin agus tá sé go hiomlán saor in aisce. Cuireann tú tionscadail leis, agus faigheann gach tionscadal ceannaire agus foireann bheag. Déanann tú comhrá leis an gceannaire, beagán cosúil le Discord, agus cuireann tú síos ar smaoineamh; déanann an ceannaire cártaí agus plean de, agus fanann sé ansin go mbrúfaidh tú Go. Oibríonn an fhoireann tríd na cártaí in ord tábhachta, ag baint úsáide as líne ordaithe shimplí a rinneadh do mhúnlaí teanga. Sula dtagann aon rud ar ais chugat, leanann tástálaí AI na céimeanna i gcóip den aip agus ceanglaíonn sé seatnóg leis. Tagann an obair chríochnaithe isteach i do charn leis na comhaid athraithe agus an diff. Glacann tú leis, nó fágann tú trácht agus dúisíonn an fhoireann agus bainfidh sí triail eile as. Ní féidir ach leatsa cárta a bhogadh go Déanta.","Lá le AI-gile, thart faoi. Tráthnóna, fágann tú cúpla trácht: tá an cnaipe seo san áit mhícheart, ba chóir an liosta sin a shórtáil, an bhféadfaimis mód dorcha a fháil. Téann tú a luí. Léann na gníomhairí na tráchtanna, déanann siad na hathruithe, tástálann siad iad agus tugann siad ar ais chugat iad. Má thránn Le déanamh, líonann faire na hoíche é ón mbacklog le cártaí nach dteastaíonn freagra uait orthu. Ar maidin tá carn gearr amháin ann: cúpla ceist agus cúpla rud le triail, gach ceann acu le céimeanna ar féidir le duine codlatach iad a leanúint agus seatnóg de é ag obair. Cliceálann tú tríd, glacann tú leis na cinn mhaithe agus seolann tú an chuid eile ar ais. Taispeánann áireamhán comharthaí cad a d'úsáid sé seo ar fad, agus tá Mód Gan Chomharthaí ann do sheachtainí gann. Ansin itheann tú do bhricfeasta, rud nach féidir leis na gníomhairí cabhrú leis fós.","Ar dtús, cad nach ea AI-gile. Ní tosaitheoir é, níl sé le díol, agus níl aon duine ag bailiú do chuid sonraí. Is bord saor é a ritheann ar do ríomhaire, gan chuntais, gan lorgairí agus gan fianáin. Cad is ann dó: áit néata amháin chun gach tionscadal códaithe AI a fheiceáil ag an am céanna, le foireann gníomhairí ag déanamh na gcártaí agus tusa ag déanamh na gcinntí. Cuireann sé cártaí gaolmhara le chéile, ceartaíonn sé teidil mhearaithe, agus coinníonn sé súil ar cé chomh héadrom agus a fhanann an cód. Labhraíonn sé thart ar 120 teanga, ón Ollainnis agus an Phléimeannais go dtí cainteanna na bpíoráidí agus Klingon. Is féidir le cairde teachtaireachtaí a sheoladh dá chéile, go príobháideach agus criptithe. Thóg Rich agus a lán gníomhairí foighneacha é, den chuid is mó ag baint úsáide as féin. Tá sé i réamh-alfa dúnta, mar sin tá sé garbh in áiteanna. Má shamhlaíonn tú go mbeadh spraoi ann, fiafraigh go múinte agus b'fhéidir go mbeidh tú istigh go luath."]}],"quips":{"1":"Focal amháin. Dána. B'fhéidir ró-dhána.","3":"Trí fhocal. Níos macánta cheana ná formhór na leathanach táirge.","8":"Ocht bhfocal. Níos giorra fós ná cruinniú seasaimh.","21":"Pointí scéil atá sna faid, dála an scéil. Ar ndóigh.","55":"Caoga cúig fhocal. Críochnaíodh dhá chárta fad a bhí tú ag léamh sin.","144":"Sin an ceann fada. Níl 233 ann. Tá na gníomhairí imithe a luí."}},"timeline":{"first-idea.name":"An chéad smaoineamh","first-idea.line":"An chéad chomhrá riamh, sula raibh cód ar bith ann.","first-board.name":"An chéad bhord","first-board.line":"Bord a lorgaíonn a thógáil féin: cártaí, colúin, tarraing agus scaoil, tionscadail.","team-roles.name":"Foireann agus róil","team-roles.line":"Próifílí gníomhairí, teimpléid foirne, spásanna agus cé a dhéanann cad.","install.name":"Suiteáil agus eisiúintí","install.line":"Zip is féidir le cara a shuiteáil, féinuasdátú, cainéil agus filleadh ar ais.","usage-saver.name":"Sábhálaí úsáide","usage-saver.line":"Tomhais cad a chosnaíonn rith, coinnigh an cód éadrom, caomhnaigh do theorainn.","friends.name":"Cairde agus comhroinnt","friends.line":"Teachtaireachtaí príobháideacha, athsheachadán mearaithe, cuirí, róil agus tionscadail chomhroinnte.","languages.name":"Teangacha","languages.line":"Gach téacs scáileáin i gcomhad teanga, an Ollainnis agus an Phléimeannais ar dtús.","ai-tester.name":"Tástálaí AI","ai-tester.line":"Seiceálann tástálaí gach tabhairt thar láimhe ar dtús agus taispeánann sé a bhfaca sé.","website.name":"An suíomh gréasáin","website.line":"aigile.lol, an teaser agus an amlíne seo.","streaming.name":"Comhrá agus sruthú","streaming.line":"Discord, Twitch, OBS, mód sruthaitheora, GIFanna agus emoji.","no-ai.name":"Eagrán gan AI","no-ai.line":"Bord do dhaoine a chódaíonn gan AI, agus boird phoiblí.","night-watch.name":"Faire na hoíche","night-watch.line":"Coinníonn fairtheoir agus Scrum Master na foirne ar an tasc agus tú i do chodladh.","p-more.name":"Gach rud eile","p-more.line":"Smaointe níos lú atá fós ag fanacht lena seal.","p-android.name":"Fón agus Android","p-android.line":"Teacht ar do bhord ó fhón, ansin aip dhúchasach Android.","p-release.name":"Alfa agus níos faide","p-release.line":"Alfa dúnta, an suíomh beo, ansin béite.","p-languages.name":"Tuilleadh teangacha","p-languages.line":"130 teanga, agus mód tumoideachais d'fhoghlaimeoirí.","p-engines.name":"Tuilleadh inneall AI","p-engines.line":"Roghnaigh Claude, Codex, Gemini, Copilot nó Cursor do gach gníomhaire.","p-pro.name":"Cleachtas gairmiúil","p-pro.line":"Lipéid riosca, geataí cumasctha, cártaí teagmhais agus ráillí cosanta.","p-self.name":"Aire a thabhairt duit féin","p-self.line":"Mód tuirse, meabhrúcháin féinchúraim agus 4:20.","p-servers.name":"Freastalaithe agus scála","p-servers.line":"Socruithe freastalaí domhanda, róil agus pleanáil don fhás.","p-livestream.name":"Breiseáin sruthaithe","p-livestream.line":"Comhrá Twitch, emoji saincheaptha agus radharc beo poiblí."},"words":{"button":"📖 Béarlagair na hearnála","h":"📖 Focail mínithe","intro":"Oiliúint saor in aisce i dteanga shimplí: gach focal a bhuailfidh leat ó chéad smaoineamh go seirbhís a bhfuil daoine ag brath uirthi, agus Agile, tógáil, sábháilteacht agus obair le AI ar an mbealach.","search":"Cuardaigh focal…","none":"Níl focal ar bith ag teacht leis sin.","close":"Dún","count":{"one":"{count} focal","other":"{count} focal"},"groups":[{"id":"idea","name":"💡 Smaointe agus fiosrú"},{"id":"plan","name":"🗺️ An obair a phleanáil"},{"id":"agile","name":"🔁 Modhanna oibre Agile"},{"id":"build","name":"🛠️ É a thógáil"},{"id":"test","name":"🧪 Tástáil agus cáilíocht"},{"id":"change","name":"🔀 É a athrú go sábháilte"},{"id":"run","name":"🛎️ Seirbhís a reáchtáil"},{"id":"sec","name":"🔒 Slándáil agus príobháideachas"},{"id":"ai","name":"🤖 Ag obair le AI"},{"id":"money","name":"💰 Airgead agus ceadúnais"}],"list":[{"id":"discovery","g":"idea","word":"Fiosrú","text":"An chéad chéim ina bhfiosraítear cén fhadhb is fiú a réiteach agus cé dó, sula dtógtar rud ar bith.","also":["céim an fhiosraithe","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Ráiteas faidhbe","text":"Abairt nó dhó a deir cé aige a bhfuil fadhb, cad í agus cén fáth a bhfuil sí tábhachtach, ionas go mbeidh an sprioc chéanna ag cách.","also":["ráitis faidhbe","problem statements"]},{"id":"user","g":"idea","word":"Úsáideoir","text":"Duine a úsáideann an rud a thógann tú. Déantar an obair chun freastal ar a riachtanais.","also":["úsáideoirí","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Páirtí leasmhar","text":"Duine ar bith a bhfuil suim aige i dtoradh na hoibre nó a mbíonn tionchar aige air, ar nós an té a íocann as, a úsáideann é nó a thacaíonn leis.","also":["páirtithe leasmhara","stakeholders"]},{"id":"persona","g":"idea","word":"Pearsa úsáideora","text":"Duine cumtha ach inchreidte a sheasann do chineál úsáideora, ionas gur féidir leis an bhfoireann fiafraí: “an mbeadh sé seo éasca do Sam?”","also":["pearsana úsáideora","personas"]},{"id":"userresearch","g":"idea","word":"Taighde úsáideoirí","text":"Labhairt le fíordhaoine agus breathnú orthu chun a riachtanais a thuiscint, seachas buille faoi thuairim a thabhairt.","also":["agallaimh le húsáideoirí","user interviews"]},{"id":"journey","g":"idea","word":"Turas úsáideora","text":"Na céimeanna a thógann duine chun rud a dhéanamh, ón gcéad uair a chloiseann sé faoi go dtí an deireadh, fiú lasmuigh de do tháirge. Léiríonn léaráid cá mbíonn sé sáinnithe.","also":["turais úsáideoirí","turas custaiméara","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pointe crá","text":"Rud a chuireann isteach ar dhaoine nó a mhoillíonn iad anois. Cuireann táirgí maithe deireadh leis na deacrachtaí sin.","also":["pointí crá","pain points"]},{"id":"assumption","g":"idea","word":"Toimhde","text":"Rud a chreideann tú ach nach bhfuil seiceáilte agat fós. Má scríobhann tú do chuid toimhdí síos, feicfidh tú cad ba cheart a thástáil ar dtús.","also":["toimhdí","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipitéis","text":"Tuairim atá tú chun a sheiceáil, agus an toradh a bhfuil súil agat leis, mar shampla “cláróidh daoine má tá an chéad mhí saor in aisce”.","also":["hipitéisí","hypotheses"]},{"id":"experiment","g":"idea","word":"Turgnamh","text":"Triail bheag phleanáilte le fáil amach an n-oibríonn smaoineamh, sula gcuirtear mórán i mbaol air.","also":["turgnaimh","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Cruthúnas coincheapa (PoC)","text":"Triail thapa gharbh le fáil amach an féidir le smaoineamh oibriú ar chor ar bith. Caitear amach í de ghnáth nuair atá an freagra agat.","also":["PoC","cruthúnas coincheapa","proof of concept"]},{"id":"prototype","g":"idea","word":"Fréamhshamhail","text":"Samhail luath den táirge, go minic pictiúir inchliceáilte, chun an smaoineamh a thriail le daoine sula dtógtar i gceart é.","also":["fréamhshamhlacha","prototypes"]},{"id":"wireframe","g":"idea","word":"Sceitse scáileáin","text":"Sceitse simplí de scáileán a léiríonn cá dtéann rudaí, gan dathanna ná fíorábhar.","also":["sceitsí scáileáin","wireframes"]},{"id":"mockup","g":"idea","word":"Mionsamhail","text":"Pictiúr mionsonraithe den chuma a bheidh ar scáileán, le fíordhathanna agus téacs, ach ní oibríonn rud ar bith fós.","also":["mionsamhlacha","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Cás gnó","text":"Na cúiseanna le tionscadal a dhéanamh: a chostas, an t-ioncam nó an coigilteas a thiocfaidh as, agus na rioscaí.","also":["cásanna gnó","business cases"]},{"id":"feasibility","g":"idea","word":"Indéantacht","text":"An féidir rud a thógáil agus aire a thabhairt dó leis an am, an t-airgead agus na scileanna atá agat.","also":["indéanta"]},{"id":"outcome","g":"idea","word":"Toradh","text":"An t-athrú atá uait do dhaoine, mar shampla níos lú coinní caillte. Tá sé níos tábhachtaí ná an méid a thógann tú.","also":["torthaí","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Aschur","text":"Rud a dhéanann an fhoireann, mar scáileán nua nó tuairisc. Ní chiallaíonn sé gur cuidiú é do dhuine ar bith díreach toisc go ndearnadh é.","also":["aschuir","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Tomhas ratha","text":"Uimhir a léiríonn ar bhain an obair a cuspóir amach, mar shampla níos mó daoine ag críochnú a n-ordaithe.","also":["tomhais ratha","success metrics"]},{"id":"kpi","g":"idea","word":"Príomhtháscaire feidhmíochta (KPI)","text":"Uimhir thábhachtach a ndéanann tú monatóireacht uirthi le feiceáil an bhfuil ag éirí go maith leat, mar líon na gclárúchán sa tseachtain.","also":["KPI","KPIs","príomhtháscaire feidhmíochta","key performance indicator"]},{"id":"okr","g":"idea","word":"Cuspóirí agus príomhthorthaí (OKRs)","text":"Modh le spriocanna a shocrú: deir an cuspóir cad atá uait, agus léiríonn roinnt príomhthorthaí in uimhreacha gur bhain tú amach é.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Táirge","text":"An rud atá á thógáil agus á chothabháil dá úsáideoirí, mar aip, suíomh gréasáin nó uirlis.","also":["táirgí","products"],"noTip":1},{"id":"vision","g":"plan","word":"Fís táirge","text":"Ráiteas gearr faoi cé a fhaigheann cuidiú ón táirge agus cén treo atá aige san fhadtéarma.","also":["ráiteas físe","vision statement"]},{"id":"po","g":"plan","word":"Úinéir táirge (PO)","text":"An duine a roghnaíonn cad a thógfar agus cén t-ord, ionas go n-oibreoidh an fhoireann ar an rud is tábhachtaí i gcónaí. In AI-gile, is tusa é sin.","also":["PO","úinéirí táirge","product owners"]},{"id":"pm","g":"plan","word":"Bainisteoir táirge (PM)","text":"An duine a thugann aire do threo an táirge: na fadhbanna a réitíonn sé, cé dó agus cén fáth. Is féidir go gciallóidh PM bainisteoir tionscadail freisin, mar sin seiceáil cé acu atá i gceist.","also":["bainisteoirí táirge","product managers"]},{"id":"projmgr","g":"plan","word":"Bainisteoir tionscadail","text":"An duine a choinníonn tionscadal in am agus laistigh den bhuiséad, ag rianú cé a dhéanann cad agus cathain.","also":["bainisteoirí tionscadail","project managers"]},{"id":"roadmap","g":"plan","word":"Treochlár","text":"Plean garbh ar a bhfuil le teacht sna míonna amach romhainn, in ord. Léiríonn sé treo seachas dátaí beachta, agus athraíonn sé de réir mar a fhoghlaimíonn tú.","also":["treochláir","roadmaps"]},{"id":"milestone","g":"plan","word":"Cloch mhíle","text":"Pointe sa tionscadal is fiú a mharcáil, mar “an chéad leagan beo” nó “100 úsáideoir”.","also":["clocha míle","milestones"]},{"id":"mvp","g":"plan","word":"Táirge inmharthana íosta (MVP)","text":"An leagan is lú de tháirge atá úsáideach do dhaoine fós, ionas gur féidir leat foghlaim uathu go luath.","also":["MVP","MVPs","táirge inmharthana íosta","minimum viable product"]},{"id":"requirement","g":"plan","word":"Riachtanas","text":"Rud nach mór don táirge críochnaithe a dhéanamh, nó tréith nach mór a bheith aige.","also":["riachtanais","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Raon feidhme","text":"An méid atá san obair agus, chomh tábhachtach céanna, an méid nach bhfuil inti.","also":["laistigh den raon","lasmuigh den raon","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Fás gan srian ar an raon","text":"Nuair a chuirtear níos mó leis an obair de réir a chéile gan comhaontú ar an am ná ar an gcostas breise, agus ní chríochnaítear go deo í.","also":["feature creep","fás gnéithe"]},{"id":"feature","g":"plan","word":"Gné","text":"Rud amháin is féidir leis an táirge a dhéanamh do dhaoine, mar “do phasfhocal a athshocrú”.","also":["gnéithe","features"],"noTip":1},{"id":"epic","g":"plan","word":"Eipic","text":"Píosa oibre atá rómhór le déanamh in aon iarracht amháin, agus mar sin roinntear ina chártaí níos lú é.","also":["eipicí","epics"]},{"id":"story","g":"plan","word":"Scéal úsáideora","text":"Píosa beag oibre ó thaobh an úsáideora de: “Mar shiopadóir, ba mhaith liom mo chiseán a shábháil chun críochnú níos déanaí.” Cuireann sé tús le comhrá faoin rud atá le tógáil.","also":["scéalta úsáideoirí","user stories"]},{"id":"ac","g":"plan","word":"Critéir ghlactha (AC)","text":"Na seiceálacha a chaithfidh cárta a shárú le bheith déanta, aontaithe sula dtosaítear, mar “fanann an ciseán ann tar éis logáil amach agus isteach arís”.","also":["critéir ghlactha","acceptance criteria"]},{"id":"task","g":"plan","word":"Tasc","text":"Obair aonair le déanamh, go minic céim bheag i scéal níos mó.","also":["tascanna","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticéad","text":"Focal eile ar chárta: píosa oibre nó iarratas a rianaítear ó thús go deireadh.","also":["ticéid","tickets"]},{"id":"priority","g":"plan","word":"Tosaíocht","text":"Cé chomh tábhachtach nó práinneach atá rud i gcomparáid leis an gcuid eile, ionas go ndéantar an obair is tábhachtaí ar dtús.","also":["tosaíochtaí","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Tosaíochtaí a shocrú","text":"Obair a chur in ord tábhachta. Modh coitianta is ea MoSCoW: riachtanach, ba cheart, d'fhéadfaí, agus ní an uair seo.","also":["tosaíocht a thabhairt","MoSCoW"]},{"id":"estimate","g":"plan","word":"Meastachán","text":"An tuairim is fearr faoi mhéid nó fad píosa oibre. Tuairim atá ann, ní gealltanas.","also":["meastacháin","meastóireacht","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Pointí scéil","text":"Méid oibre a mheas trí chártaí a chur i gcomparáid (“thart ar dhá oiread an chinn sin”), seachas in uaireanta. Ní úsáidtear iad le foirne a chur i gcomparáid.","also":["pointe scéil","story point"]},{"id":"tshirt","g":"plan","word":"Meas de réir méideanna T-léine","text":"Méid na hoibre a mheas mar S, M, L nó XL. Tapa agus sách cruinn don luathphleanáil.","also":["méideanna T-léine","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Pócar pleanála","text":"Cluiche meastacháin: taispeánann gach duine cárta méide ag an am céanna, ansin míníonn na daoine leis an meastachán is airde agus is ísle a gcúiseanna.","also":["Scrum poker","pócar Scrum"]},{"id":"dependency","g":"plan","word":"Spleáchas","text":"Nuair nach féidir píosa oibre a thosú nó a chríochnú go dtí go dtosaítear nó go gcríochnaítear ceann eile.","also":["spleáchais","dependencies"]},{"id":"blocker","g":"plan","word":"Bac","text":"Rud ar bith a chuireann stop leis an obair anois, mar fhreagra atá ar iarraidh nó uirlis bhriste.","also":["baic","blockers"]},{"id":"deadline","g":"plan","word":"Spriocdháta","text":"An dáta faoina gcaithfear rud a chríochnú.","also":["spriocdhátaí","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Táirge insoláthartha","text":"Rud nithiúil a thagann as an obair agus a thugtar ar láimh, mar leathanach a oibríonn nó tuairisc.","also":["táirgí insoláthartha","deliverables"]},{"id":"forecast","g":"plan","word":"Réamhaisnéis","text":"Tuar ar an rud is dóichí a tharlóidh, mar cathain a bheidh an obair déanta, bunaithe ar a bhfuil ar eolas agat.","also":["réamhaisnéisí","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Méadracht","text":"Rud ar bith a thomhaiseann tú thar am, mar chuairteanna leathanaigh nó an fad a thógann deisiú.","also":["méadrachtaí","metrics"]},{"id":"feedback","g":"plan","word":"Aiseolas","text":"An méid a deir daoine faoi do chuid oibre, idir mhaith agus olc. Tá aiseolas luath rialta i gcroílár Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"An liosta feithimh de smaointe agus d’obair nach bhfuil pleanáilte fós, an rud is tábhachtaí ar bharr. Ní dhéantar aon rud ansin go dtí go n-aistrítear é go Le déanamh."},{"id":"sprint","g":"agile","word":"Sprint","text":"Tréimhse ghearr, shocraithe oibre (seachtain nó dhó go minic, gan níos mó ná mí riamh) le sprioc agus tacar cártaí comhaontaithe le críochnú.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Seiceáil ghasta laethúil: cad a rinne gach ball den fhoireann, cad a dhéanfaidh siad ar aghaidh, agus cad atá á gcosc. In Scrum, tugtar an daily scrum air.","also":["standup","stand-ups","daily scrum","daily stand-up","scrum laethúil"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Bealach oibre ina mbogann cártaí trasna cholúin an bhoird (mar Le déanamh, Ar siúl, Déanta) agus ina gcuireann an fhoireann teorainn leis an méid atá ar siúl ag an am céanna, ionas go leanann an obair ag sreabhadh."},{"id":"wip","g":"agile","word":"WIP limit","text":"Is é is brí le WIP ná ‘work in progress’, .i. obair atá ar siúl. Is é teorainn WIP an líon is mó cártaí ba chóir do cholún a choinneáil ag an am céanna, ionas go gcríochnaíonn an fhoireann rudaí sula dtosaíonn siad ar níos mó.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Seicliosta gearr na foirne ar cad is brí le “críochnaithe”, mar shampla tástáilte agus mínithe, sula dtugtar cárta duit. Insíonn a cúpla, an Definition of Ready, cathain atá cárta soiléir go leor le tosú air.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Súil siar rialta ar an gcaoi a n-oibríonn an fhoireann, chun aontú ar rud nó dhó le déanamh níos fearr an chéad uair eile. Gearrfhoirm de ‘retrospective’ (aisbhreathnú). In AI-gile molann retro athrú ar bhealaí oibre na foirne, agus deir tusa Go nó Ní fós.","also":["retros","aisbhreathnú","aisbhreathnuithe"]},{"id":"swarm","g":"agile","word":"Saithe","text":"Gach duine i bhfeidhm: scaoileann go leor daoine obair eile uathu chun rud práinneach amháin a réiteach le chéile go dtí go bhfuil sé socraithe. In AI-gile cuidíonn gach foireann le tionscadal amháin, agus fanann tionscadail eile idir an dá linn.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"In Scrum, an duine a chabhraíonn leis an bhfoireann oibriú go maith: glanann sé na rudaí a chuireann bac orthu, coinníonn sé cruinnithe ar an mbóthar ceart agus cóitseálann sé dea-nósanna, gan aon duine a ordú. In AI-gile tugann an Lead Scrum Master faoi deara cártaí atá i bhfostú, spreagann sé na foirne agus meabhraíonn sé duit cad atá ag fanacht, thar gach tionscadal.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Obair i gcéimeanna beaga: tóg beagán, taispeáin torthaí rialta, foghlaim ón aiseolas agus athraigh an plean de réir mar a théann tú, seachas gach rud a phleanáil roimh ré.","also":["forbairt lúfar","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Forógra Agile","text":"Ráiteas gearr ó fhorbróirí bogearraí in 2001. Cuireann sé daoine, torthaí oibre, comhoibriú le custaiméirí agus freagairt d'athruithe chun tosaigh ar phleananna troma agus páipéarachas.","also":["Forógra um Fhorbairt Lúfar Bogearraí","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Samhail an easa","text":"An seanmhodh: gach rud a phleanáil, gach rud a thógáil, ansin gach rud a thástáil, céim ar chéim. Bíonn athruithe déanacha deacair agus costasach.","also":["samhail easa","waterfall model"]},{"id":"iteration","g":"agile","word":"Atriall","text":"Babhta amháin de thógáil, seiceáil agus feabhsú. Is slabhra babhtaí den sórt sin é Agile, agus is cineál amháin é sprint.","also":["atriallta","iterations"]},{"id":"increment","g":"agile","word":"Incrimint","text":"Píosa nua a oibríonn, a chuirtear leis an táirge i sprint nó i mbabhta oibre, agus a oireann don mhéid a bhí ann cheana.","also":["incrimintí","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Modh coitianta Agile: oibríonn foireann bheag i sprintí gearra i dtreo sprice, le róil shocraithe agus cruinnithe rialta chun pleanáil, seiceáil agus feabhsú."},{"id":"scrumteam","g":"agile","word":"Foireann Scrum","text":"An grúpa beag a dhéanann an obair in Scrum: úinéir táirge, Scrum Master agus na forbróirí.","also":["foirne Scrum","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Imeachtaí Scrum","text":"Cruinnithe rialta Scrum: pleanáil sprint, an scrum laethúil, athbhreithniú sprint agus an retro (aisbhreathnú). Tugann go leor daoine searmanais orthu.","also":["searmanais","searmanais Scrum","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Pleanáil sprint","text":"Cruinniú ag tús sprint ina n-aontaíonn an fhoireann cén fáth a bhfuil sé tábhachtach, cé na cártaí a thógfar agus conas tosú.","also":["cruinniú pleanála","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprioc sprint","text":"Abairt amháin a deir cad chuige an sprint. Is féidir tascanna beaga a athrú má bhaintear an sprioc amach.","also":["spriocanna sprint","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Riaráiste sprint (sprint backlog)","text":"Na cártaí a roghnaíodh don sprint reatha, agus plean na foirne lena ndéanamh.","also":["riaráistí sprint","backlog","sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Riaráiste táirge (product backlog)","text":"An liosta iomlán in ord de gach rud a d'fhéadfaí a thógáil don táirge, an rud is tábhachtaí ar barr. Athraíonn sé de réir mar a fhoghlaimíonn tú.","also":["riaráistí táirge","backlog","product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Sprioc táirge","text":"An toradh mór a bhfuil an táirge ag díriú air, a chabhraíonn leis an bhfoireann an chéad obair eile a roghnú.","also":["spriocanna táirge","product goals"]},{"id":"refinement","g":"agile","word":"Beachtú an riaráiste (backlog refinement)","text":"Dul tríd an backlog (an riaráiste) go rialta chun cártaí a ghlanadh, a roinnt, a ordú agus sonraí a chur leo, ionas go mbeidh siad réidh le tógáil. Tugtar glanadh riaráiste (backlog grooming) air freisin.","also":["glanadh riaráiste","beachtú","backlog","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Athbhreithniú sprint","text":"Cruinniú ag deireadh sprint ina dtaispeánann an fhoireann an obair chríochnaithe agus ina n-éisteann sí le tuairimí chun an chéad chéim eile a roghnú.","also":["athbhreithnithe sprint","sprint reviews"]},{"id":"demo","g":"agile","word":"Taispeántas","text":"Obair chríochnaithe a thaispeáint ag obair, beo, do na daoine a d'iarr í.","also":["taispeántais","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Teorainn ama","text":"Méid ama socraithe do rud. Stopann tú nuair atá sé caite, fiú mura bhfuil gach rud críochnaithe.","also":["faoi theorainn ama","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Luas foirne","text":"An méid oibre a chríochnaíonn foireann de ghnáth i sprint, a úsáidtear chun a phleanáil cé mhéad a thógfaidh sí an chéad uair eile. Ní scór é ar chomh dian is a oibríonn daoine.","also":["luas na foirne","team velocity"]},{"id":"capacity","g":"agile","word":"Acmhainn","text":"An méid oibre is féidir leis an bhfoireann a dhéanamh i dtréimhse, tar éis saoire agus jabanna eile a chur san áireamh.","noTip":1},{"id":"burndown","g":"agile","word":"Cairt na hoibre fágtha","text":"Cairt a léiríonn an obair atá fágtha i sprint ag laghdú gach lá. Má fhanann an líne cothrom, tá rud sáinnithe.","also":["burndown","burn-down chart","cairt dóite síos"]},{"id":"burnup","g":"agile","word":"Cairt na hoibre déanta","text":"Cairt ina n-ardaíonn an obair chríochnaithe thar am, in aice leis an iomlán pleanáilte, chun a thaispeáint cathain a bheidh tú réidh.","also":["burnup","burn-up chart","cairt dóite suas"]},{"id":"kanbanboard","g":"agile","word":"Bord Kanban","text":"An bord féin: colún do gach céim den obair, agus cártaí ag bogadh trasna.","also":["boird Kanban","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Córas tarraingthe","text":"Modh oibre ina dtosaítear obair nua nuair a bhíonn spás ag duine í a ghlacadh, seachas í a bhrú ar dhuine atá lán go béal cheana.","also":["bunaithe ar tharraingt","pull-based"]},{"id":"flow","g":"agile","word":"Sreabhadh","text":"Cé chomh réidh a ghluaiseann obair trasna an bhoird. Le sreabhadh maith, bogann cártaí ar aghaidh seachas carnadh suas.","also":["sreabhadh oibre","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Aga seachadta","text":"An t-am ón iarratas go dtí go bhfuil an rud críochnaithe.","also":["agaí seachadta","lead times"]},{"id":"cycletime","g":"agile","word":"Am timthrialla","text":"An t-am ó thús iarbhír na hoibre ar chárta go dtí go bhfuil sé críochnaithe.","also":["amanna timthrialla","cycle times"]},{"id":"throughput","g":"agile","word":"Tréchur","text":"Líon na gcártaí a chríochnaítear i seachtain nó i dtréimhse shocraithe eile.","also":["ráta tréchuir","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Scrogall","text":"An chéim ina gcarnann obair agus ina moillítear gach rud taobh thiar di, cosúil le muineál caol buidéil.","also":["scrogaill","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Lána","text":"Sraith trasna an bhoird a chuireann cártaí den chineál céanna le chéile, mar obair phráinneach nó cártaí foirne amháin.","also":["lánaí","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Modh oibre a chuireann deireadh le cur amú (rud nach gcabhraíonn leis an gcustaiméir) agus a choinníonn obair ag sreabhadh."},{"id":"waste","g":"agile","word":"Cur amú","text":"In Lean, iarracht nach gcabhraíonn leis an gcustaiméir, mar fheitheamh, athobair nó rudaí nach n-úsáideann aon duine a thógáil.","noTip":1},{"id":"kaizen","g":"agile","word":"Feabhsú leanúnach","text":"Feabhas beag a chur ar rudaí an t-am ar fad trí athruithe beaga rialta, agus seiceáil ansin ar chabhraigh siad. Bealach amháin chuige is ea an retro. Tugtar kaizen air freisin.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Foireann fhéineagraithe","text":"Foireann a roghnaíonn féin conas an obair a dhéanamh, seachas treoracha céim ar chéim a fháil.","also":["féineagraithe","foireann fhéinbhainistithe","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Foireann thrasfheidhmeach","text":"Foireann a bhfuil na scileanna ar fad aici chun an obair a chríochnú féin, mar dhearadh, tógáil agus tástáil.","also":["trasfheidhmeach","cross-functional"]},{"id":"spike","g":"agile","word":"Triail taighde","text":"Taighde gearr le teorainn ama chun ceist a fhreagairt sula dtugtar faoin bhfíorobair.","also":["trialacha taighde","spikes"]},{"id":"rework","g":"agile","word":"Athobair","text":"Obair a dhéanamh arís toisc nach raibh sí ceart an chéad uair.","also":["athdhéanta","reworked"]},{"id":"safe","g":"agile","word":"Agile ar scála (SAFe)","text":"Bealaí le Agile a úsáid thar go leor foirne in eagraíocht mhór. Sampla aitheanta is ea SAFe (Scaled Agile Framework).","also":["Agile ar scála","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Fillteán cóid an tionscadail, lena stair iomlán de commits. Féadann sé a bheith ar do ríomhaire, ar GitHub, nó ar an dá cheann.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Líne oibre ar leith sa chód, ionas gur féidir athruithe a dhéanamh gan teagmháil a dhéanamh leis an bpríomhleagan.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Grianghraf sábháilte den chód, le nóta gearr faoin méid a d’athraigh. Is féidir leat filleadh ar cheann ar bith i gcónaí.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Do ghrianghraif shábháilte (commits) a sheoladh ón ríomhaire seo chuig an gcóip roinnte ar líne, mar GitHub, ionas go mbeidh cúltaca orthu agus go mbeidh daoine eile in ann iad a fháil."},{"id":"merge","g":"build","word":"Merge","text":"Athruithe ó bhrainse amháin a cheangal le brainse eile, de ghnáth ar ais isteach sa phríomhleagan."},{"id":"pr","g":"build","word":"Pull request","text":"Iarraidh go ndéanfaí athruithe brainse a sheiceáil agus a chumasc leis an bpríomhleagan. Tugann roinnt suíomhanna merge request air.","also":["PR","PRs","merge request","iarraidh cumaisc"]},{"id":"refactor","g":"build","word":"Refactor","text":"An cód a ordú gan a bhfuil á dhéanamh aige a athrú: comhaid níos lú, ainmneacha níos soiléire, níos lú athrá."},{"id":"bug","g":"build","word":"Bug","text":"Rud nach n-oibríonn mar ba chóir.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Athbhreithniú piaraí","text":"Péire súl eile: seiceálann duine seachas an t-údar an obair sula sroicheann sí thú, ionas go dtéann níos lú botún tríd. In AI-gile seiceálann AI eile gach cárta.","also":["athbhreithniú cóid","code review","peer review"]},{"id":"code","g":"build","word":"Cód","text":"Na treoracha scríofa a insíonn do ríomhaire cad le déanamh. Tugtar cód foinseach air freisin.","also":["cód foinseach","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Teanga ríomhchlárúcháin","text":"Teanga chun cód a scríobh, mar JavaScript, Python nó Java. Oireann teangacha éagsúla do jabanna éagsúla.","also":["teangacha ríomhchlárúcháin","programming languages"]},{"id":"developer","g":"build","word":"Forbróir (dev)","text":"Duine a scríobhann agus a athraíonn cód. Tugtar ríomhchláraitheoir nó innealtóir bogearraí air freisin.","also":["forbróir","forbróirí","ríomhchláraitheoir","innealtóir bogearraí","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Bogearraí","text":"Cláir a ritheann ar ríomhairí agus ar fhóin, seachas na gléasanna féin (na crua-earraí).","noTip":1},{"id":"app","g":"build","word":"Aip","text":"Gearr ar fheidhmchlár: clár a úsáideann daoine le rud a dhéanamh ar fhón, ar ríomhaire nó i mbrabhsálaí gréasáin.","also":["aipeanna","feidhmchlár","feidhmchláir","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Aip ghréasáin","text":"Aip a ritheann i mbrabhsálaí gréasáin, mar sin níl aon rud le suiteáil.","also":["aipeanna gréasáin","web apps","web application"]},{"id":"frontend","g":"build","word":"Comhéadan tosaigh","text":"An chuid d'aip a fheiceann tú agus a gcliceálann tú uirthi: scáileáin, cnaipí agus focail, go minic i do bhrabhsálaí.","also":["front-end","frontend","comhéadan tosaigh"]},{"id":"backend","g":"build","word":"Cúlchóras","text":"An chuid folaithe d'aip a stórálann sonraí agus a dhéanann an obair nuair a chliceálann tú rud, mar do phasfhocal a sheiceáil.","also":["back-end","backend","cúlchóras"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Obair ar an gcomhéadan tosaigh agus ar an gcúlchóras araon.","also":["full-stack"]},{"id":"ui","g":"build","word":"Comhéadan úsáideora (UI)","text":"An méid a fheiceann agus a úsáideann duine ar an scáileán: leagan amach, cnaipí, roghchláir agus téacs.","also":["UI","comhéadan úsáideora","user interface"]},{"id":"ux","g":"build","word":"Eispéireas úsáideora (UX)","text":"Conas a bhraitheann sé rud a úsáid: éasca, soiléir agus taitneamhach, nó mearbhallach agus mall.","also":["UX","eispéireas úsáideora","user experience"]},{"id":"accessibility","g":"build","word":"Inrochtaineacht (a11y)","text":"Rudaí a dhéanamh inúsáidte do chách, lena n-áirítear daoine nach bhfeiceann go maith, nach féidir leo luch a úsáid nó a úsáideann léitheoir scáileáin.","also":["a11y"]},{"id":"responsive","g":"build","word":"Dearadh freagrúil","text":"Leathanaigh a chur in oiriúint d'aon mhéid scáileáin, ó fhón go monatóir mór, ionas go n-oibreoidh siad go maith.","also":["freagrúil"]},{"id":"designsys","g":"build","word":"Córas dearaidh","text":"Tacar comhroinnte dathanna, clónna, cnaipí agus rialacha, ionas go mbeidh an chuma agus an t-iompar céanna ar gach scáileán.","also":["córais dearaidh","design systems"]},{"id":"architecture","g":"build","word":"Ailtireacht","text":"Cruth foriomlán córais: a phríomhchodanna agus an chaoi a ndéanann siad cumarsáid lena chéile."},{"id":"database","g":"build","word":"Bunachar sonraí (DB)","text":"Stór faisnéise eagraithe, cosúil le scarbhileog an-chumhachtach ar féidir leis an aip a léamh agus a athrú.","also":["bunachar sonraí","bunachair sonraí","database","databases","DB"]},{"id":"schema","g":"build","word":"Scéimre bunachair sonraí","text":"Leagan amach bunachair sonraí: na táblaí atá ann agus an méid a théann i ngach ceann.","also":["scéimre","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Gearr ar theanga struchtúrtha iarratas: teanga le faisnéis a iarraidh ar go leor bunachar sonraí nó a athrú iontu.","also":["Teanga Struchtúrtha Iarratas","Structured Query Language"]},{"id":"data","g":"build","word":"Sonraí","text":"Faisnéis a choinníonn ríomhaire, mar ainmneacha, orduithe nó socruithe.","also":["tacar sonraí","tacair sonraí","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Freastalaí","text":"Ríomhaire atá ar siúl i gcónaí agus a fhreagraíonn iarratais ó ríomhairí eile, mar leathanach gréasáin a sheoladh nuair a thugann tú cuairt air.","also":["freastalaithe","servers"]},{"id":"client","g":"build","word":"Cliant","text":"An taobh a iarrann rud, do bhrabhsálaí nó d'aip de ghnáth, agus é ag caint le freastalaí. I ngnó, ciallaíonn sé custaiméir freisin.","also":["cliaint","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Gearr ar chomhéadan feidhmchláir (application programming interface): roghchlár seasta iarratas is féidir le clár amháin a chur ar chlár eile, mar shampla réamhaisnéis an lae a iarraidh ar sheirbhís aimsire.","also":["APIs","comhéadan feidhmchláir","application programming interface"]},{"id":"endpoint","g":"build","word":"Críochphointe","text":"Mír amháin ar roghchlár API: seoladh gréasáin ar féidir le clár glaoch air chun rud a fháil nó a sheoladh.","also":["críochphointí","endpoints"]},{"id":"integration","g":"build","word":"Comhtháthú","text":"Dhá chóras a cheangal le go n-oibreoidh siad le chéile, mar do shiopa ag seoladh orduithe chuig do bhogearraí cuntasaíochta.","also":["comhtháthuithe","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Teachtaireacht a sheolann córas go córas eile go huathoibríoch a luaithe a tharlaíonn rud, mar “íocaíocht faighte”.","also":["webhooks","crúcaí gréasáin"]},{"id":"library","g":"build","word":"Leabharlann","text":"Cód réidh a scríobh duine eile agus ar féidir leat a athúsáid seachas é a scríobh tú féin.","also":["leabharlanna","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Creatlach","text":"Struchtúr réidh chun aip a thógáil a shocraíonn cuid mhór de leagan amach an chóid, cosúil le fráma tí a líonann tú isteach.","also":["creatlacha","frameworks"]},{"id":"sdk","g":"build","word":"Trealamh forbartha bogearraí (SDK)","text":"Bosca uirlisí, cóid agus samplaí chun bogearraí a thógáil d'ardán nó do sheirbhís amháin.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Spleáchas bogearraí","text":"Leabharlann nó uirlis a theastaíonn ó do chód le hoibriú. Tá sé tábhachtach iad a choinneáil cothrom le dáta ar mhaithe le slándáil.","also":["spleáchais bogearraí","software dependencies"]},{"id":"package","g":"build","word":"Pacáiste","text":"Beart de chód réidh ar féidir leat a shuiteáil agus a úsáid i dtionscadal.","also":["pacáistí","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Bainisteoir pacáistí","text":"Uirlis a fhaigheann agus a nuashonraíonn na pacáistí a bhfuil do chód ag brath orthu. Sampla coitianta is ea npm.","also":["bainisteoirí pacáistí","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"An uirlis is coitianta chun stair athruithe cóid a choinneáil, mar commits agus brainsí."},{"id":"github","g":"build","word":"GitHub","text":"Suíomh gréasáin a choinníonn repos Git ar líne, ionas gur féidir le foirne cód a roinnt, athruithe a athbhreithniú agus obair a rianú."},{"id":"vcs","g":"build","word":"Rialú leaganacha","text":"Stair iomlán gach athraithe comhaid a choinneáil, chun a fheiceáil cé a d'athraigh cad agus dul siar más gá. Déanann Git é seo.","also":["rialú foinse","córas rialaithe leaganacha","source control","version control system"]},{"id":"clone","g":"build","word":"Clónáil","text":"Do chóip iomlán féin de repo, lena stair, a dhéanamh ar do ríomhaire.","also":["clónáilte","clónáil","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (tarraingt)","text":"Na commits is déanaí a fháil ón gcóip chomhroinnte, mar GitHub, ar do ríomhaire. A mhalairt de push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Príomhbhrainse","text":"Leagan oifigiúil an chóid a n-oibríonn gach duine uaidh, ar a dtugtar main nó master go minic.","also":["brainse master","master branch"]},{"id":"conflict","g":"build","word":"Coinbhleacht chumaisc","text":"Nuair a bhaineann dhá athrú leis na línte céanna ar bhealaí difriúla, ionas nach féidir leis an ríomhaire iad a chur le chéile agus go gcaithfidh duine roghnú.","also":["coinbhleachtaí cumaisc","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (difríocht)","text":"Amharc a léiríonn go díreach cad a d'athraigh idir dhá leagan: línte curtha leis agus bainte amach.","also":["diffs","difríochtaí"]},{"id":"fork","g":"build","word":"Fork (forcáil)","text":"Do chóip féin de repo duine eile, ar féidir leat a athrú gan cur isteach ar a gcóip siúd.","also":["forks","forked","forcáilte"]},{"id":"script","g":"build","word":"Script","text":"Clár gearr a dhéanann jab amháin go huathoibríoch, mar chomhaid a ghlanadh nó an aip a thosú.","also":["scripteanna","scripts"],"noTip":1},{"id":"build","g":"build","word":"Tógáil","text":"Cód a iompú ina rud atá réidh le rith, nó an toradh réidh féin.","also":["tógálacha","builds"],"noTip":1},{"id":"compile","g":"build","word":"Tiomsú","text":"Cód scríofa ag daoine a aistriú go foirm ar féidir leis an ríomhaire a rith go díreach.","also":["tiomsaithe","tiomsaitheoir","tiomsú","compiler"]},{"id":"cli","g":"build","word":"Líne na n-orduithe (CLI)","text":"Fuinneog téacs ina scríobhann tú treoracha don ríomhaire seachas cliceáil. Tugtar teirminéal uirthi freisin.","also":["líne na n-orduithe","teirminéal","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Cumraíocht (config)","text":"Na socruithe a rialaíonn iompar bogearraí, ar leith ón gcód ionas go mbeidh siad éasca a athrú.","also":["config","cumraíocht","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Athróg timpeallachta","text":"Socrú a thugtar do chlár nuair a thosaíonn sé, go minic do sheoltaí nó pasfhocail ionas nach scríobhtar sa chód iad.","also":["athróga timpeallachta","environment variables","env var"]},{"id":"debugging","g":"build","word":"Dífhabhtú","text":"An chúis a aimsiú nach n-oibríonn rud, agus é a cheartú.","also":["dífhabhtaigh","dífhabhtaithe","debug","debugged"]},{"id":"pairing","g":"build","word":"Ríomhchlárú beirte","text":"Beirt, nó duine agus AI, ag obair ar an gcód céanna le chéile: duine amháin ag clóscríobh agus an duine eile ag seiceáil.","also":["obair bheirte","pairing"]},{"id":"docs","g":"build","word":"Doiciméadú (docs)","text":"Mínithe scríofa ar an gcaoi a n-oibríonn rud nó a úsáidtear é.","also":["doiciméadú","cáipéisí","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"An chéad chomhad le léamh i repo: cad é an tionscadal agus conas é a chur ag obair.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Córas oidhreachta","text":"Seanchóras atá fós in úsáid agus atá deacair a athrú, go minic toisc nach dtuigeann ach beagán daoine é a thuilleadh.","also":["córais oidhreachta","cód oidhreachta","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Fiachas teicniúil","text":"Aicearraí a shábhálann am anois ach a mhoillíonn athruithe níos déanaí, cosúil le hiasacht a charnann ús. Laghdaíonn athstruchtúrú (refactor) é.","also":["fiachas teicniúil","tech debt"]},{"id":"test","g":"test","word":"Test","text":"Seiceáil go n-oibríonn rud mar ba chóir. Ritheann an ríomhaire roinnt tástálacha leis féin gach uair a athraítear an cód; i gcás tástálacha eile, is tusa a thriaileann cárta críochnaithe sula nglacann tú leis.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Gearrfhoirm de ‘quality assurance’, .i. dearbhú cáilíochta: gach rud a dhéantar chun a chinntiú go bhfuil obair ceart sula dtéann sí beo. In AI-gile, is iad sin na seiceálacha uathoibríocha: nuair a bhíonn QA dearg, theip ar rud éigin, agus ní féidir é a chur beo go dtí go socraítear é.","also":["dearbhú cáilíochta","seiceálacha cáilíochta","quality assurance"]},{"id":"testpile","g":"test","word":"Carn tástála","text":"Na cártaí críochnaithe atá ag fanacht leat iad a thriail, ceann i ndiaidh a chéile. Glac le ceann nó seol ar ais é le nóta, agus tagann an chéad cheann eile.","also":["carnanna tástála"]},{"id":"autotest","g":"test","word":"Tástáil uathoibrithe","text":"Seiceáil a ritheann an ríomhaire as féin gach uair a athraíonn an cód, chun botúin a aimsiú go luath.","also":["tástálacha uathoibrithe","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Tástáil de láimh","text":"Duine ag triail na hoibre de láimh le fáil amach an n-oibríonn sí mar is ceart.","also":["tástálacha de láimh","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Tástáil aonaid","text":"Seiceáil bheag uathoibríoch ar phíosa beag bídeach cóid as féin.","also":["tástálacha aonaid","unit tests"]},{"id":"integtest","g":"test","word":"Tástáil chomhtháthaithe","text":"Seiceáil go n-oibríonn roinnt codanna i gceart le chéile, ní ceann ar cheann amháin.","also":["tástálacha comhtháthaithe","integration tests"]},{"id":"endtoend","g":"test","word":"Tástáil ó cheann ceann (E2E)","text":"Tástáil a ghníomhaíonn mar fhíorúsáideoir ó thús go deireadh, mar chlárú, ceannach agus íoc.","also":["E2E","ó cheann ceann","end-to-end tests"]},{"id":"uat","g":"test","word":"Tástáil ghlactha úsáideoirí (UAT)","text":"Baineann na daoine a d'iarr an obair triail aisti féin agus deir siad an bhfreastalaíonn sí orthu. Is é carn tástála AI-gile a leagan féin de seo.","also":["UAT","tástáil ghlactha","acceptance testing"]},{"id":"regression","g":"test","word":"Aischéimniú","text":"Rud a bhí ag obair ach a bhris tar éis athraithe. Seiceálann tástálacha aischéimnithe go n-oibríonn na seanrudaí fós.","also":["aischéimnithe","tástáil aischéimnithe","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Buntástáil","text":"Seiceáil an-tapa go n-oibríonn na príomhrudaí ar chor ar bith, mar shampla díreach tar éis athrú a chur beo. Má theipeann uirthi, stop agus féach.","also":["buntástálacha","smoke tests"]},{"id":"exploratory","g":"test","word":"Tástáil thaiscéalaíoch","text":"An táirge a thriail go saor ar bhealaí éagsúla chun fadhbanna a aimsiú nach dtabharfadh seiceálacha pleanáilte faoi deara.","also":["tástáil thaiscéalaíoch","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Cás tástála","text":"Cás scríofa amháin le triail: na céimeanna agus an toradh ba cheart a bheith ann.","also":["cásanna tástála","test cases"]},{"id":"coverage","g":"test","word":"Clúdach tástála","text":"An méid den chód a sheiceálann tástálacha uathoibríocha. Is sábháilte níos mó de ghnáth, ach ní chruthaíonn clúdach ard leis féin go n-oibríonn rud go maith.","also":["clúdach","clúdach cóid","code coverage"]},{"id":"testdata","g":"test","word":"Sonraí tástála","text":"Faisnéis shamplach chumtha le haghaidh tástála, ionas nach nochtar sonraí príobháideacha fíordhaoine.","also":["sonraí samplacha","test fixtures"]},{"id":"edgecase","g":"test","word":"Cás imeallach","text":"Cás neamhghnách ag na teorainneacha, mar fhoirm fholamh nó ainm le huaschamóg, ina mbriseann rudaí go minic.","also":["cásanna imeallacha","edge cases"]},{"id":"happypath","g":"test","word":"An gnáthbhealach rathúil","text":"An gnáthbhealach ina n-éiríonn le gach rud. Déanann tástáil mhaith triail ar na bealaí nach n-éiríonn leo freisin."},{"id":"perftest","g":"test","word":"Tástáil feidhmíochta","text":"Seiceáil cé chomh tapa is atá rud agus cé chomh maith is a sheasann sé brú.","also":["tástáil feidhmíochta","tástálacha feidhmíochta","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Tástáil ualaigh","text":"Seiceáil conas a éiríonn le córas nuair a úsáideann go leor daoine é ag an am céanna.","also":["tástáil ualaigh","tástálacha ualaigh","load test","load tests"]},{"id":"sectest","g":"test","word":"Tástáil slándála","text":"Laigí a lorg a ligfeadh do dhuine córas a mhí-úsáid nó rudaí nár cheart dó a fheiceáil.","also":["tástáil slándála","tástálacha slándála","security test","security tests"]},{"id":"accesstest","g":"test","word":"Tástáil inrochtaineachta","text":"Seiceáil gur féidir le daoine le cumais éagsúla an táirge a úsáid, lena n-áirítear le léitheoir scáileáin nó le méarchlár amháin.","also":["tástáil inrochtaineachta","accessibility test"]},{"id":"linting","g":"test","word":"Linting (seiceáil stíle)","text":"Seiceáil uathoibríoch a aimsíonn botúin dhóchúla agus stíl mhíshlachtmhar i gcód, cosúil le seiceálaí litrithe do chláir.","also":["linter","lint","seiceálaí cóid"]},{"id":"static","g":"test","word":"Anailís statach","text":"Cód a léamh go huathoibríoch chun fadhbanna a aimsiú, gan é a rith.","also":["anailís statach cóid","static code analysis"]},{"id":"flaky","g":"test","word":"Tástáil éagobhsaí","text":"Tástáil a n-éiríonn léi uaireanta agus a dteipeann uirthi uaireanta eile gan chúis shoiléir, mar sin ní féidir brath go hiomlán uirthi.","also":["tástálacha éagobhsaí","flaky tests"]},{"id":"repro","g":"test","word":"Atáirgeadh (repro)","text":"Fabht a chur ag tarlú arís d'aon ghnó leis na céimeanna céanna, ionas gur féidir é a fhiosrú agus a dheisiú. Is iad na céimeanna sin, scríofa síos, an chuid is úsáidí de thuairisc ar fhabht.","also":["repro","atáirgeadh","céimeanna atáirgthe","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Déine","text":"Cé chomh dona is atá tionchar faidhbe, ó bheagán crá go stop iomlán.","also":["leibhéal déine","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Leagan nua de na bogearraí a chóipeáil ar na ríomhairí a rithfidh iad, mar chóip thástála nó an tseirbhís bheo."},{"id":"release","g":"change","word":"Eisiúint","text":"Beart ainmnithe d’obair chríochnaithe a théann beo le chéile, le nótaí gearra ar cad a d’athraigh. Scríobhann 🚀 Eisiúintí na nótaí ó na cártaí atá déanta.","also":["eisiúintí","release","leagan"]},{"id":"rollback","g":"change","word":"Rolladh siar","text":"Dul ar ais go dtí an leagan deireanach a d’oibrigh nuair a chruthaíonn ceann nua trioblóid. In AI-gile, bailíonn Rolladh siar na céimeanna cealaithe a scríobhadh ar gach athrú in aon seicliosta amháin.","also":["rollback","roll back","dul siar"]},{"id":"live","g":"change","word":"Beo","text":"An fíorleagan a úsáideann daoine, seachas cóip chun rudaí a thriail. Tugann forbróirí production air freisin.","also":["live","táirgeadh","production"],"noTip":1},{"id":"change","g":"change","word":"Athrú","text":"Athrú pleanáilte ar rud a mbíonn daoine ag brath air, scríofa síos ar dtús: cad é, cén fáth, an riosca, cathain, agus conas é a chealú. Tosaigh ceann le 🔀 Ardaigh athrú.","also":["athruithe","iarratas ar athrú","iarratais ar athrú"],"noTip":1},{"id":"risk","g":"change","word":"Riosca","text":"Rud a d’fhéadfadh dul amú, le scór de réir chomh dóchúil agus chomh dona is a bheadh sé. Coinníonn ⚠️ Rioscaí iad in aon liosta amháin, an scór is airde ar dtús, agus dáta ag gach ceann chun breathnú air arís.","also":["rioscaí","clár rioscaí"]},{"id":"chgwin","g":"change","word":"Fuinneog athraithe","text":"Na hamanna a bhfuil cead ag athruithe dul beo, mar shampla tráthnóna Dé Máirt ciúin. Taobh amuigh d’fhuinneog ní féidir cárta athraithe a chríochnú, mura éigeandáil atá ann.","also":["fuinneoga athraithe"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Seiceáil dheireanach díreach sula dtéann athrú beo: deir gach duine a gcaithfidh formheas a thabhairt Go nó No go. Ní théann sé ar aghaidh ach nuair a deir gach duine Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Cead","text":"Fanacht le freagra dearfach sula dtosaíonn an obair. Fanann cárta a chruthaíonn cara, nó athrú, i ✅ Ceadanna go dtí go gceadaíonn tú nó go ndiúltaíonn tú é.","also":["ceadanna","ceadú"]},{"id":"quiettime","g":"change","word":"Am ciúin","text":"Tréimhse, mar le linn sruthú beo, taispeántais nó thar oíche, nuair nach dtéann tada beo. Leanann na foirne ag obair agus ag tástáil, ach fanann dul beo go dtí go dtagann deireadh léi. In áiteanna eile tugtar change freeze uirthi.","also":["amanna ciúine","reo athruithe","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Modh oibre ina mbíonn lucht tógála agus lucht reáchtála bogearraí ina bhfoireann amháin, le mórán uathoibrithe, chun athruithe a chur beo go minic agus go sábháilte."},{"id":"cicd","g":"change","word":"CI/CD (comhtháthú agus seachadadh leanúnach)","text":"Cuirtear athruithe gach duine sa phríomhleagan go minic agus seiceáiltear go huathoibríoch gach uair iad (comhtháthú leanúnach), ionas go mbíonn na bogearraí réidh le dul beo le brú cnaipe (seachadadh leanúnach).","also":["CI/CD","CI","CD","comhtháthú leanúnach","seachadadh leanúnach","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Imscaradh leanúnach","text":"Céim níos faide ná seachadadh leanúnach: téann gach athrú a éiríonn leis sna seiceálacha beo as féin, gan cnaipe a bhrú.","also":["imscarthaí leanúnacha","continuous deployments"]},{"id":"pipeline","g":"change","word":"Píblíne","text":"An tsraith uathoibríoch céimeanna a théann athrú tríothu ar a bhealach beo, mar thógáil, tástáil agus imscaradh.","also":["píblínte","pipelines"]},{"id":"environment","g":"change","word":"Timpeallacht","text":"Cóip ar leith den chóras le cuspóir amháin, mar chóip le tógáil inti, cóip le tástáil inti agus an chóip bheo.","also":["timpeallachtaí","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Timpeallacht forbartha","text":"An chóip a n-oibríonn forbróir inti, go minic ar a ríomhaire féin, áit nach ndéanann briseadh dochair do dhuine ar bith.","also":["timpeallacht forbróra","dev environment"]},{"id":"testenv","g":"change","word":"Timpeallacht tástála","text":"Cóip ar leith den chóras le haghaidh tástála amháin, ionas nach gcuirtear isteach ar an bhfíorsheirbhís.","also":["timpeallachtaí tástála","test environments"]},{"id":"staging","g":"change","word":"Timpeallacht réamhbheo","text":"Cóip dheireanach atá socraithe díreach mar an tseirbhís bheo, chun seiceáil deiridh a dhéanamh roimh dhul beo.","also":["timpeallacht réamhbheo","staging environment"]},{"id":"artifact","g":"change","word":"Déantán tógála","text":"An comhad nó an beart a chruthaíonn tógáil, réidh le stóráil, seiceáil nó cur beo.","also":["déantáin tógála","build artifacts"]},{"id":"hotfix","g":"change","word":"Deisiú práinneach","text":"Deisiú práinneach a chuirtear beo go tapa lasmuigh den ghnáthphlean, toisc go bhfuil rud tábhachtach briste.","also":["deisiúcháin phráinneacha","hotfixes"]},{"id":"patch","g":"change","word":"Paiste","text":"Nuashonrú beag a dheisíonn fabht nó bearna slándála. Tá sé tábhachtach paistí slándála a chur i bhfeidhm go tapa.","also":["paistí","paiste slándála","paistí slándála","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Uimhir leagain","text":"Lipéad mar 2.4.1 a léiríonn cén eisiúint atá agat. Is minic a athraíonn an chéad uimhir le hathruithe móra agus an ceann deireanach le deisiúcháin bheaga.","also":["uimhreacha leagain","leaganú séimeantach","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Nótaí eisiúna","text":"Liosta gearr soiléir d'athruithe eisiúna do na húsáideoirí, lena n-áirítear deisiúcháin agus srianta aitheanta. Tugtar loga athruithe air freisin.","also":["loga athruithe","changelog","change log"]},{"id":"flag","g":"change","word":"Bratach gné","text":"Lasc chun gné a chur ar siúl nó as, ionas gur féidir le hobair nua dul beo i bhfolach agus a chur ar siúl (nó a mhúchadh arís) gan eisiúint nua.","also":["bratacha gné","lasc gné","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Dul ar aghaidh le deisiú","text":"Droch-eisiúint a dheisiú trí leagan ceartaithe nua a chur amach go tapa seachas filleadh ar an seancheann.","also":["dul ar aghaidh","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Eisiúint chanáraí","text":"Athrú a chur beo do ghrúpa beag ar dtús, agus do chách nuair is léir go bhfuil sé ceart. Ainmnithe as na canáraithe a thógadh mianadóirí faoin talamh mar luathrabhadh.","also":["eisiúintí canáraí","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Imscaradh gorm-uaine","text":"Dhá chóip den chóras beo a choinneáil agus daoine a aistriú go dtí an ceann nua in aon iarracht amháin, ionas gur féidir filleadh láithreach má theipeann air.","also":["gorm-uaine","blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Imscaradh gan aga neamhfhónaimh","text":"Leagan nua a chur beo gan stop ar bith sa tseirbhís do na húsáideoirí.","also":["gan aga neamhfhónaimh","zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Éascú athruithe","text":"Cuidiú le hathruithe a bheith rathúil: an riosca a mheas, an cead ceart a fháil agus am maith a roghnú. Tugtar bainistíocht athruithe air freisin.","also":["bainistíocht athruithe","change management"]},{"id":"cab","g":"change","word":"Bord comhairleach athruithe (CAB)","text":"Grúpa a athbhreithníonn athruithe tábhachtacha agus a aontaíonn an féidir leo dul ar aghaidh agus cathain.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Athrú caighdeánach","text":"Athrú ísealriosca a dhéantar ar an mbealach cruthaithe céanna gach uair, agus a cheadaítear roimh ré dá bhrí sin.","also":["athruithe caighdeánacha","standard changes"]},{"id":"normchange","g":"change","word":"Gnáthathrú","text":"Athrú nach mór a sheiceáil agus a cheadú sula dtéann sé ar aghaidh.","also":["gnáthathruithe","normal changes"]},{"id":"emergchange","g":"change","word":"Athrú éigeandála","text":"Athrú nach mór a dhéanamh láithreach chun trioblóid thromchúiseach a dheisiú nó a chosc, le ceadú níos tapa dá réir.","also":["athruithe éigeandála","emergency changes"]},{"id":"automation","g":"change","word":"Uathoibriú","text":"An ríomhaire a chur ag déanamh jab athfhillteach as féin, níos tapa agus ar an mbealach céanna gach uair.","also":["uathoibrithe","automated"],"noTip":1},{"id":"infra","g":"change","word":"Bonneagar","text":"Na ríomhairí, líonraí agus seirbhísí a ritheann bogearraí orthu.","also":["infra","bonneagar"]},{"id":"iac","g":"change","word":"Bonneagar mar chód (IaC)","text":"Cur síos ar do fhreastalaithe agus do shocruithe i gcomhaid in éineacht leis an gcód, ionas gur féidir iad a atógáil ar an mbealach céanna gach uair.","also":["IaC"]},{"id":"cloud","g":"change","word":"Néal","text":"Ríomhairí, stóráil agus seirbhísí a fháil ar cíos ó sholáthraí mór ar an idirlíon, seachas na gléasanna a bheith agat féin.","also":["an néal","néalríomhaireacht","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Soláthraí néil","text":"Cuideachta a chuireann ríomhaireacht ar cíos ar an idirlíon, mar Amazon Web Services (AWS), Microsoft Azure nó Google Cloud.","also":["soláthraithe néil","cloud providers"]},{"id":"hosting","g":"change","word":"Óstáil","text":"An áit a bhfuil d'aip nó do shuíomh gréasáin á rith ionas gur féidir le daoine é a bhaint amach, ar cíos ó chuideachta de ghnáth.","also":["óstáilte"]},{"id":"domain","g":"change","word":"Ainm fearainn","text":"An seoladh gréasáin a chlóscríobhann daoine, mar example.com. Faigheann tú ar cíos é in aghaidh na bliana, mar sin ní mór é a athnuachan.","also":["ainmneacha fearainn","fearann","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Gearr ar chóras ainmneacha fearainn: leabhar seoltaí an idirlín, a athraíonn ainm mar example.com go seoladh an ríomhaire cheart.","also":["córas ainmneacha fearainn","domain name system"]},{"id":"container","g":"change","word":"Coimeádán","text":"Pacáiste dúnta ina bhfuil aip agus gach rud a theastaíonn uaithi, ionas go ritheann sí mar an gcéanna ar aon ríomhaire. Is é Docker an uirlis is aitheanta.","also":["coimeádáin","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Meaisín fíorúil (VM)","text":"Ríomhaire insamhlaithe ag rith laistigh d'fhíor-ríomhaire, ionas gur féidir le gléas mór amháin feidhmiú mar go leor gléasanna.","also":["VM","VMs","meaisíní fíorúla","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (gan freastalaí féin)","text":"Cód a rith gan aire a thabhairt d'fhreastalaithe tú féin: ritheann an soláthraí é nuair is gá agus íocann tú as an méid a úsáideann tú."},{"id":"lb","g":"change","word":"Cothromóir ualaigh","text":"Rud a roinneann cuairteoirí ar roinnt freastalaithe ionas nach mbíonn aon cheann acu faoi iomarca brú.","also":["cothromóirí ualaigh","load balancers"]},{"id":"cache","g":"change","word":"Taisce","text":"Stór áisiúil de thorthaí le déanaí a choinnítear in aice láimhe, ionas nach gá an rud céanna a fháil ná a oibriú amach arís. Má ghlantar é, is minic a dheisítear leathanaigh a bhfuil cuma as dáta orthu.","also":["taiscí","taisceadh","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Líonra seachadta ábhair (CDN)","text":"Líonra domhanda freastalaithe a choinníonn cóipeanna de do leathanaigh agus do phictiúir gar do chuairteoirí, ionas go lódálann siad go tapa.","also":["CDN"]},{"id":"migration","g":"change","word":"Aistriú","text":"Sonraí nó córais a bhogadh ó sheansocrú go socrú nua, nó leagan amach bunachair sonraí a athrú go cúramach.","also":["aistrithe","aistriú bunachair sonraí","migrations","database migration"]},{"id":"service","g":"run","word":"Seirbhís","text":"Rud a thóg tú a mbíonn daoine ag brath air, mar shampla suíomh gréasáin nó aip, a dtugtar aire dó ionas go leanann sé ag obair. Cuir tic le “Is seirbhís é an tionscadal seo” agus abair cad a thairgeann sé, cé a úsáideann é agus cé atá ar dualgas.","also":["seirbhísí","service"]},{"id":"uptimepct","g":"run","word":"Aga fónaimh","text":"An méid ama a mbíonn seirbhís ag obair, mar chéatadán de ghnáth. Ceadaíonn 99.9% thart ar 43 nóiméad neamhfhónaimh sa mhí fós.","also":["céatadán aga fónaimh","uptime percentage"]},{"id":"uptime","g":"run","word":"Seiceáil uptime","text":"Seiceáil uathoibríoch, gach cúpla nóiméad, go bhfuil do sheirbhís fós ag freagairt. Má theipeann uirthi roinnt uaireanta as a chéile, osclaíonn AI-gile cárta eachtra as a stuaim féin.","also":["uptime","seiceálacha uptime","uptime checks","infhaighteacht"]},{"id":"statuspage","g":"run","word":"Leathanach stádais","text":"Leathanach poiblí a thaispeánann an bhfuil seirbhís ag obair (glas, oráiste nó dearg) leis an nuashonrú is déanaí, ionas gur féidir leis na daoine a úsáideann í féachaint air in ionad ceisteanna a chur.","also":["leathanaigh stádais","status page"]},{"id":"desk","g":"run","word":"Deasc seirbhíse","text":"An áit a dtagann ceisteanna agus tuairiscí isteach ó na daoine a úsáideann do sheirbhís. Sórtálann AI-gile gach ceann mar iarratas, eachtra nó smaoineamh, agus deir sé é nuair is cosúil le rud a tuairiscíodh cheana.","also":["deasca seirbhíse","deasc","service desk","deasc chabhrach"]},{"id":"svcrequest","g":"run","word":"Iarratas seirbhíse","text":"Duine ag iarraidh rud gnáth, mar shampla cuntas nua nó beagán cabhrach, seachas a thuairisciú go bhfuil rud briste. Fanann sé ar a sheal; téann eachtra roimhe.","also":["iarratais seirbhíse"]},{"id":"incident","g":"run","word":"Eachtra","text":"Rud atá briste nó nach n-oibríonn i gceart do na daoine atá á úsáid faoi láthair, mar shampla an suíomh gréasáin a bheith as feidhm nó an-mhall. Léimeann cárta eachtra 🔥 an scuaine: is é an chéad rud é a chur ag obair arís.","also":["eachtraí","incident"]},{"id":"major","g":"run","word":"Mór-eachtra","text":"Eachtra mhór: go leor daoine thíos leis, nó airgead nó sonraí i mbaol. Cuireann cnaipe amháin gach foireann ag obair air (saithe), dúisíonn sé an té atá ar dualgas agus iarrann sé nuashonrú stádais gach 30 nóiméad.","also":["mór-eachtraí","major incident"]},{"id":"oncall","g":"run","word":"Ar dualgas","text":"Is tú an duine a fhreagraíonn nuair a bhriseann rud éigin, fiú san oíche. Tá ball foirne ar dualgas ag gach seirbhís a dhúisítear ar dtús dá cuid eachtraí.","also":["dualgas","on call","on-call"]},{"id":"replyby","g":"run","word":"Am freagartha","text":"An fad is féidir le cárta fanacht le céad fhreagra, mar shampla uair an chloig d’eachtra. Ina dhiaidh sin faigheann sé clog dearg, ionas nach ndéantar dearmad ar aon rud gan fhios. Tugtar sprioc freagartha air freisin.","also":["amanna freagartha","sprioc freagartha","spriocanna freagartha"]},{"id":"postmortem","g":"run","word":"Iarbhreithniú","text":"Súil ghearr siar tar éis eachtra: cad a tharla, cad a chabhraigh agus cad ba cheart a athrú, gan an milleán a chur ar aon duine. Ní féidir eachtra a dhúnadh gan ceann.","also":["iarbhreithnithe","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Fadhb","text":"An chúis fholaithe taobh thiar d’eachtra amháin nó níos mó. Cuireann cárta 🧩 fadhbanna eachtraí a thagann ar ais arís agus arís eile le chéile, ionas go n-aimsítear an chúis agus go ndeisítear í go deo.","also":["fadhbanna"],"noTip":1},{"id":"rootcause","g":"run","word":"Bunchúis","text":"An fíorchúis ar bhris rud éigin, ní hamháin an rud a chonaic tú ag dul amú. Deisigh an bhunchúis agus ní thiocfaidh an eachtra ar ais.","also":["bunchúiseanna","root cause"]},{"id":"workaround","g":"run","word":"Bealach timpeall","text":"Slí chun rudaí a choinneáil ag obair go dtí go mbíonn an fíordheisiú réidh, mar shampla rud a atosú nuair a théann sé i bhfostú. Scríobhtar é ar an gcárta fadhbanna ionas nach mbeidh ar aon duine é a oibriú amach arís.","also":["bealaí timpeall","réiteach sealadach","workaround"]},{"id":"knownerror","g":"run","word":"Earráid aitheanta","text":"Fadhb a bhfuil a cúis tuigthe ach nach bhfuil socraithe go fóill, de ghnáth le réiteach sealadach scríofa síos. Liostaíonn 🧩 Earráidí aitheanta iad, ionas go n-úsáideann gach duine an réiteach sealadach in ionad tochailt arís.","also":["earráidí aitheanta","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Treoracha céim ar chéim chun cineál aitheanta trioblóide a réiteach, ionas go ndéantar é ar an mbealach céanna, go tapa, gach uair. Tar éis eachtra mhór is féidir leis an bhfoireann ceann a mholadh duit le go dtabharfá OK dó.","also":["runbooks","lámhleabhar oibríochta"]},{"id":"ci","g":"run","word":"Mír chumraíochta","text":"Rud amháin a bhfuil do sheirbhís ag brath air, mar shampla freastalaí, fearann, teastas, eochair nó soláthraí. Liostaíonn 🗂️ Míreanna cumraíochta iad de réir seirbhíse, ionas go bhfeicfidh tú cad a mbíonn tionchar ag eachtra air agus cad is gá a athnuachan nó cúltaca a dhéanamh de.","also":["míreanna cumraíochta","mír cumraíochta","CI"]},{"id":"expiry","g":"run","word":"Dáta éaga","text":"An dáta a stopann rud ag obair mura n-athnuaitear é, mar theastas slándála suímh gréasáin nó a sheoladh gréasáin. Coinníonn AI-gile súil ar na dátaí seo agus déanann sé cárta amháin chun gach ceann a athnuachan 30 lá roimh ré, ionas nach stopann aon rud gan choinne.","also":["dátaí éaga","éag","faire éaga"]},{"id":"backup","g":"run","word":"Cúltaca","text":"Cóip shábháilte de do shonraí ó níos luaithe, le dul siar uirthi má chailltear nó má dhéantar damáiste do rud éigin. Déanann AI-gile cúltaca de do chláir gach lá.","also":["cúltacaí","backup","cóip chúltaca"]},{"id":"restore","g":"run","word":"Athchóiriú","text":"Sonraí a chur ar ais ó chúltaca. Ní fiú cúltaca i ndáiríre go dtí go mbíonn a fhios agat gur féidir é a athchóiriú, mar sin is fiú é a thriail anois is arís.","also":["athchóirigh","athchóirithe","restore"]},{"id":"svcreview","g":"run","word":"Athbhreithniú seirbhíse","text":"Súil siar ar mhí amháin de sheirbhís: eachtraí a osclaíodh agus a deisíodh, cé chomh tapa a fuair daoine freagra, am ar fáil agus tocáin a úsáideadh. Taispeánann an tAthbhreithniú míosúil é do gach seirbhís.","also":["athbhreithnithe seirbhíse","athbhreithniú míosúil","athbhreithnithe míosúla"]},{"id":"accessreview","g":"run","word":"Athbhreithniú rochtana","text":"Seiceáil gach 90 lá cé atá in ann dul isteach fós: naisc roinnte, róil cairde agus pasfhocail agus eochracha sábháilte. Coinníonn tú gach ceann nó baineann tú é, ionas nach bhfanann seanrochtain.","also":["athbhreithnithe rochtana"]},{"id":"improvements","g":"run","word":"Liosta feabhsuithe","text":"Gach rud ar shocraigh an fhoireann feabhas a chur air, in aon áit amháin: moltaí retro, gníomhartha athbhreithnithe agus socruithe fadhbanna, gach ceann lena stádas. Gheobhaidh tú é faoi 📈 Feabhsuithe.","also":["liostaí feabhsuithe","feabhsuithe"]},{"id":"tokencap","g":"run","word":"Uasteorainn tocán","text":"Teorainn mhíosúil ar na tocáin is féidir le gníomhairí seirbhíse a úsáid. Ag 80% faigheann tú rabhadh; ag 100% fanann a gcuid oibre cúlra go dtí an mhí seo chugainn nó go dtí go n-ardaíonn tú an uasteorainn.","also":["uasteorainneacha tocán","uasteorainn tocán míosúil","token cap"]},{"id":"svcmgmt","g":"run","word":"Bainistíocht seirbhíse","text":"Gach rud a bhaineann le seirbhís a choinneáil úsáideach agus ag obair do na daoine a bhíonn ag brath uirthi, lá i ndiaidh lae.","also":["seirbhís a bhainistiú"]},{"id":"itil","g":"run","word":"ITIL","text":"Treoir a úsáidtear go forleathan don dea-bhainistíocht seirbhíse, a chlúdaíonn rudaí mar eachtraí, fadhbanna agus athruithe. Sheas an t-ainm tráth do IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Bainistíocht seirbhísí TF (ITSM)","text":"Teicneolaíocht a reáchtáil mar sheirbhís do dhaoine, le bealaí soiléire chun iarratais, eachtraí, athruithe agus feabhsuithe a láimhseáil.","also":["ITSM"]},{"id":"managed","g":"run","word":"Seirbhís bhainistithe","text":"Seirbhís a reáchtálann duine eile duit, faoi chomhaontú maidir le cé chomh maith a chaithfidh sí oibriú.","also":["seirbhísí bainistithe","managed services"]},{"id":"svcowner","g":"run","word":"Úinéir seirbhíse","text":"An duine atá freagrach as an tseirbhís ina hiomláine: a feidhmíocht, a costas agus a feabhsú.","also":["úinéirí seirbhíse","service owners"]},{"id":"sla","g":"run","word":"Comhaontú leibhéil seirbhíse (SLA)","text":"Gealltanas scríofa do chustaiméirí faoin tseirbhís, mar “ar fáil 99.9% den am” nó “freagra laistigh d'uair”, le haisíocaíocht go minic má sháraítear é.","also":["SLA","SLAs","comhaontú leibhéil seirbhíse","service level agreement"]},{"id":"slo","g":"run","word":"Cuspóir leibhéil seirbhíse (SLO)","text":"Sprioc na foirne féin maidir le feidhmíocht seirbhíse thar thréimhse, níos déine de ghnáth ná an SLA ar mhaithe le sábháilteacht.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Táscaire leibhéil seirbhíse (SLI)","text":"An tomhas iarbhír a chuirtear i gcomparáid leis an sprioc, mar an céatadán cuairteanna a lódáil i gceart.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Infhaighteacht","text":"An féidir le daoine seirbhís a úsáid nuair is gá, rud a thomhaistear go minic mar aga fónaimh.","also":["ard-infhaighteacht","high availability"]},{"id":"downtime","g":"run","word":"Aga neamhfhónaimh","text":"Am nach mbíonn seirbhís ag obair nó a mbíonn sí múchta, bíodh sé pleanáilte nó ná bíodh.","also":["am as feidhm","down time"]},{"id":"errorbudget","g":"run","word":"Buiséad earráide","text":"An méid beag teipe a cheadaíonn do sprioc iontaofachta. Fad atá cuid de fágtha, is féidir rioscaí a ghlacadh le hathruithe; nuair atá sé caite, moillítear.","also":["buiséid earráide","error budgets"]},{"id":"outage","g":"run","word":"Briseadh seirbhíse","text":"Tréimhse ina mbíonn seirbhís as feidhm nó briste go dona dá húsáideoirí.","also":["bristeacha seirbhíse","outages"]},{"id":"degraded","g":"run","word":"Seirbhís lagaithe","text":"Ag obair, ach go dona: mall nó le codanna nach n-oibríonn.","also":["seirbhís lagaithe","degraded service"]},{"id":"monitoring","g":"run","word":"Monatóireacht","text":"Súil uathoibríoch leanúnach a choinneáil ar sheirbhís chun fadhbanna a aimsiú, go hidéalach sula dtugann úsáideoirí faoi deara iad.","also":["faoi mhonatóireacht"]},{"id":"observability","g":"run","word":"Inbhraiteacht","text":"Cé chomh maith is féidir leat a thuiscint ón taobh amuigh cad atá ar siúl laistigh de chóras, trína logaí, uimhreacha agus rianta.","also":["o11y"]},{"id":"log","g":"run","word":"Loga","text":"Dialann leanúnach a choinníonn clár ar a chuid oibre, le fáil amach cad a chuaigh amú.","also":["logaí","logáil","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Rian","text":"Taifead ar thuras iarratais trí chodanna éagsúla córais, céim ar chéim, a léiríonn cá ndeachaigh sé i moill.","also":["rianta","rianú","traces","tracing"]},{"id":"latency","g":"run","word":"Moill (latency)","text":"An fad a thógann sé ar rud freagairt, mar an fanacht idir cliceáil agus an leathanach a theacht ar an scáileán.","also":["latency"]},{"id":"alert","g":"run","word":"Foláireamh","text":"Teachtaireacht uathoibríoch go bhfuil aird ag teastáil, mar shuíomh gréasáin nach bhfreagraíonn.","also":["foláirimh","foláireamh a thabhairt","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Tuirse foláireamh","text":"Nuair atá an oiread foláireamh ann go dtosaíonn daoine ag déanamh neamhaird orthu, fiú na cinn thábhachtacha.","also":["tuirse aláraim","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Deais","text":"Scáileán a thaispeánann na huimhreacha agus na stádais is tábhachtaí le sracfhéachaint.","also":["deaiseanna","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Glao éigeandála","text":"Glaoch práinneach a chur ar an duine ar dualgas nó é a dhúiseacht faoi fhadhb.","also":["glao faighte","paged"]},{"id":"escalation","g":"run","word":"Ardú chuig leibhéal eile","text":"Duine le níos mó scile nó údaráis a thabhairt isteach nuair nach féidir ceist a réiteach ag an leibhéal reatha, nó nach féidir é a dhéanamh sách tapa.","also":["ardú","ardaithe","escalate","escalated"]},{"id":"triage","g":"run","word":"Triage (sórtáil tosaíochta)","text":"Fadhbanna nua a shórtáil go tapa de réir práinne agus tábhachta, ionas go bpléitear leis na cinn is measa ar dtús.","also":["sórtáilte de réir tosaíochta","triaged"]},{"id":"impact","g":"run","word":"Tionchar","text":"An méid a théann rud i bhfeidhm ar dhaoine: cé mhéad duine agus cé chomh dona.","noTip":1},{"id":"urgency","g":"run","word":"Práinn","text":"Cé chomh tapa is gá rud a láimhseáil. Socraíonn tionchar agus práinn an tosaíocht le chéile.","noTip":1},{"id":"plevels","g":"run","word":"Leibhéil tosaíochta (P1, P2…)","text":"Lipéid a léiríonn cé chomh práinneach atá fadhb. Is é P1 an ceann is tromchúisí agus teastaíonn gníomh láithreach uaidh.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Scuaine ticéad","text":"Liosta na n-iarratas agus na n-eachtraí atá ag fanacht go dtógfaidh duine iad.","also":["scuainí ticéad","ticket queues"]},{"id":"tiers","g":"run","word":"An chéad agus an dara líne","text":"Leibhéil tacaíochta: glacann an chéad líne leis an nglao agus réitíonn sí rudaí simplí; tá saineolas níos doimhne ag an dara líne do na cinn chasta. Tugtar leibhéal 1 agus 2 orthu freisin.","also":["an chéad líne","an dara líne","tacaíocht chéadlíne","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Ceannasaí eachtra","text":"An duine amháin a stiúrann an fhreagairt ar eachtra, ionas go mbeidh a fhios ag cách cé a chinneann agus cé a dhéanann cad.","also":["ceannasaithe eachtra","incident commanders"]},{"id":"responsetime","g":"run","word":"Am freagartha","text":"An fad a thógann sé sula nglacann duine le hiarratas nó le heachtra den chéad uair.","also":["amanna freagartha","response times"]},{"id":"resolution","g":"run","word":"Am réitigh","text":"An fad a thógann sé iarratas nó eachtra a réiteach go hiomlán, ón tuairisc go dtí an deisiú.","also":["amanna réitigh","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Meán-am téarnaimh (MTTR)","text":"Ar an meán, an fad a thógann sé seirbhís a chur ag obair arís tar éis di briseadh. Ní hionann go díreach an bhrí a bhíonn le MTTR i gcónaí, mar sin abair cad a thomhaiseann tú.","also":["MTTR","meán-am athshlánaithe","mean time to restore"]},{"id":"mtbf","g":"run","word":"Meán-am idir teipeanna (MTBF)","text":"Ar an meán, an fad a ritheann seirbhís sula mbriseann rud.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Bunachar bainistíochta cumraíochta (CMDB)","text":"Liosta do mhíreanna cumraíochta agus a gceangal lena chéile, chun a fheiceáil cad atá ag brath ar cad.","also":["CMDB"]},{"id":"asset","g":"run","word":"Sócmhainn","text":"Rud luachmhar atá agat nó a n-íocann tú as chun an tseirbhís a rith, mar ríomhaire glúine, ceadúnas bogearraí nó fearann.","also":["sócmhainní","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Pleanáil acmhainne","text":"A chinntiú go mbeidh dóthain cumhachta ríomhaireachta, stórála agus daoine ann don méid atá le teacht.","also":["plean acmhainne","capacity plan"]},{"id":"scaling","g":"run","word":"Scálú","text":"Freastal ar níos mó úsáideoirí trí níos mó cumhachta a thabhairt do ghléas (scálú suas) nó trí ghléasanna eile a chur leis (scálú amach).","also":["scálú suas","scálú amach","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Leanúnachas gnó","text":"Pleananna chun na rudaí tábhachtacha a choinneáil ag obair nuair a théann rud mór amú, mar oifig, príomhsholáthraí nó ríomhairí a chailleadh.","also":["plean leanúnachais gnó","business continuity plan"]},{"id":"dr","g":"run","word":"Athshlánú ó thubaiste (DR)","text":"An plean agus na huirlisí chun seirbhís a chur ar ais tar éis eachtra thromchúiseach, mar ionad sonraí iomlán a chailleadh.","also":["athshlánú ó thubaiste","disaster recovery"]},{"id":"rto","g":"run","word":"Sprioc ama athshlánaithe (RTO)","text":"An t-am is faide a cheadaítear do sheirbhís a bheith as feidhm tar éis tubaiste sula gcaithfidh sí oibriú arís.","also":["RTO"]},{"id":"rpo","g":"run","word":"Sprioc pointe athshlánaithe (RPO)","text":"An méid sonraí le déanaí a d'fhéadfá a chailleadh, tomhaiste in am. Ciallaíonn RPO uair an chloig cúltacaí gach uair an chloig ar a laghad.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Iomarcaíocht","text":"Páirteanna breise a bheith réidh, mar dhara freastalaí, ionas nach stopann teip amháin an tseirbhís.","also":["iomarcach"]},{"id":"failover","g":"run","word":"Aistriú teipe","text":"Aistriú go córas cúltaca go huathoibríoch nuair a theipeann ar an ngnáthchóras.","also":["aistriú ar theip","fail over"]},{"id":"spof","g":"run","word":"Pointe aonair teipe","text":"Cuid amháin a chuireann gach rud as feidhm má bhriseann sí, toisc nach bhfuil cuid spártha ann.","also":["pointí aonair teipe","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Fuinneog chothabhála","text":"Am pleanáilte a bhféadfaí seirbhís a stopadh nó a mhoilliú le haghaidh cothabhála, a fhógraítear d'úsáideoirí roimh ré.","also":["fuinneoga cothabhála","tréimhse chothabhála","cothabháil phleanáilte","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Aistriú freagrachta","text":"Obair, eolas agus freagracht a thabhairt do dhuine nó foireann eile, ionas nach gcailltear aon rud.","also":["aistrithe freagrachta","handovers"]},{"id":"kb","g":"run","word":"Bunachar eolais","text":"Bailiúchán d'ailt chabhrach agus d'fhreagraí, d'úsáideoirí agus don fhoireann.","also":["bunachair eolais","knowledge bases"]},{"id":"csat","g":"run","word":"Sástacht custaiméirí (CSAT)","text":"Scór ó úsáideoirí a léiríonn a sástacht, a iarrtar go minic tar éis iarratas a dhúnadh.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Soláthraí","text":"Cuideachta sheachtrach a mbraitheann tú uirthi, mar do sholáthraí óstála. Tugtar díoltóir nó tríú páirtí uirthi freisin.","also":["soláthraithe","díoltóir","díoltóirí","tríú páirtí","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Seirbhís a scor","text":"Seirbhís a mhúchadh go buan agus go sábháilte: úsáideoirí a chur ar an eolas, sonraí agus rochtain a láimhseáil agus deireadh a chur lena costais.","also":["seirbhís a scor","retiring a service"]},{"id":"eol","g":"run","word":"Deireadh ré (EOL)","text":"Nuair a stopann déantóir táirge de nuashonruithe nó tacaíocht a chur ar fáil dó, agus mar sin ba cheart é a athsholáthar.","also":["EOL","deireadh ré","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cibearshlándáil","text":"Córais agus sonraí a chosaint ar bhriseadh isteach, goid agus damáiste.","also":["cibearshlándáil","cyber security"]},{"id":"authn","g":"sec","word":"Fíordheimhniú","text":"A sheiceáil cé hé duine, le pasfhocal nó cód de ghnáth. Giorraítear go authn é go minic.","also":["authn"]},{"id":"authz","g":"sec","word":"Údarú","text":"A sheiceáil cad atá cead ag duine a dhéanamh tar éis a aithint cé hé. Giorraítear go authz é go minic.","also":["authz","údarú","authorization"]},{"id":"mfa","g":"sec","word":"Fíordheimhniú ilfhachtóra (MFA)","text":"Logáil isteach le dhá chruthúnas nó níos mó, mar phasfhocal agus cód ar do fhón. Tugtar défhachtóir (2FA) air freisin.","also":["MFA","2FA","défhachtóir","fíordheimhniú dhá fhachtóir","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Síniú isteach aonair (SSO)","text":"Logáil isteach uair amháin chun dul isteach i go leor córas, mar do chuntas oibre a úsáid i ngach áit.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Bainisteoir pasfhocal","text":"Aip a chruthaíonn pasfhocail láidre agus a chuimhníonn orthu duit.","also":["bainisteoirí pasfhocal","password managers"]},{"id":"secret","g":"sec","word":"Rún","text":"Pasfhocal, eochair nó cód príobháideach a úsáideann clár le rochtain a fháil. Níor cheart é a roinnt ná a scríobh sa chód riamh.","also":["rúin","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Eochair API","text":"Cód rúnda a ligeann do chlár API seirbhíse eile a úsáid agus a léiríonn cé atá á úsáid agus ag íoc as.","also":["eochracha API","API keys"]},{"id":"accesstoken","g":"sec","word":"Comhartha rochtana (access token)","text":"Pas sealadach a chruthaíonn go bhfuil cead isteach ag clár, ionas nach mbíonn do phasfhocal ag teastáil uaidh gach uair. Ní hionann é agus token AI.","also":["comharthaí rochtana","access tokens"]},{"id":"encryption","g":"sec","word":"Criptiú","text":"Faisnéis a chur i gcód ionas nach féidir ach leis an té a bhfuil an eochair cheart aige í a léamh.","also":["criptithe","criptigh","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"An bealach slán ina dtaistealaíonn leathanaigh ghréasáin, a léirítear leis an nglas i do bhrabhsálaí, ionas nach féidir le duine ar bith eatarthu iad a léamh ná a athrú."},{"id":"cert","g":"sec","word":"Teastas SSL/TLS","text":"Cárta aitheantais digiteach a ligeann do shuíomh a chéannacht a chruthú agus HTTPS a úsáid. Téann sé in éag, mar sin ní mór é a athnuachan.","also":["teastas TLS","teastas SSL","teastas","teastais","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Ceadanna","text":"Na rialacha maidir le cé a fhéadann cad a fheiceáil nó a athrú.","also":["cead","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"An phribhléid is lú","text":"Gan ach an rochtain atá de dhíth i ndáiríre a thabhairt do gach duine nó clár, agus ar feadh an ama a bhfuil gá léi amháin.","also":["prionsabal na pribhléide is lú","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Rialú rochtana de réir róil (RBAC)","text":"Rochtain a thabhairt de réir róil, mar amharcóir nó eagarthóir, seachas duine ar dhuine.","also":["RBAC","rochtain de réir róil","role-based access"]},{"id":"vuln","g":"sec","word":"Leochaileacht","text":"Laige a d'fhéadfaí a úsáid chun briseadh isteach nó dochar a dhéanamh.","also":["leochaileachtaí","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Laige atá ar eolas ag ionsaitheoirí sula mbíonn am ag na déantóirí í a dheisiú.","also":["zero-days","zero day","leochaileacht nialas lae"]},{"id":"malware","g":"sec","word":"Bogearraí mailíseacha","text":"Bogearraí díobhálacha, mar víris, a dhéantar chun damáiste, spiaireacht nó goid a dhéanamh."},{"id":"ransomware","g":"sec","word":"Bogearraí éirice","text":"Bogearraí mailíseacha a ghlasálann do chomhaid agus a éilíonn airgead lena n-oscailt. Is iad cúltacaí maithe an chosaint is fearr.","also":["ionsaí bogearraí éirice","ransomware attack"]},{"id":"phishing","g":"sec","word":"Fioscaireacht","text":"Teachtaireachtaí bréige a dhéanann iarracht tú a mhealladh le pasfhocail nó airgead a thabhairt uait, nó rud díobhálach a oscailt.","also":["ríomhphost fioscaireachta","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Innealtóireacht shóisialta","text":"Daoine, seachas ríomhairí, a mhealladh chun rochtain a thabhairt, mar ghlao bréige ó “thacaíocht TF”."},{"id":"firewall","g":"sec","word":"Balla dóiteáin","text":"Garda a chinneann cén trácht líonra a cheadaítear isteach nó amach.","also":["ballaí dóiteáin","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Gearr ar líonra príobháideach fíorúil: nasc príobháideach criptithe ar an idirlíon, a úsáidtear go minic le córais oibre a bhaint amach go sábháilte.","also":["líonra príobháideach fíorúil","virtual private network"]},{"id":"ddos","g":"sec","word":"Diúltú seirbhíse (DoS, DDoS)","text":"An oiread tráchta bréige a sheoladh chuig seirbhís nach féidir le fíordhaoine í a úsáid. Ciallaíonn DDoS go dtagann sé ó go leor ríomhairí ag an am céanna.","also":["DoS","DDoS","diúltú seirbhíse","ionsaí DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Tástáil treáite (pen test)","text":"Saineolaithe cairdiúla a fhostú chun iarracht a dhéanamh briseadh isteach, ionas go n-aimsítear laigí roimh fhíorionsaitheoirí.","also":["tástáil treáite","pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Iniúchadh slándála","text":"Seiceáil chúramach ar an gcosaint atá ann, i gcomparáid le liosta dea-chleachtais.","also":["iniúchtaí slándála","security audits"]},{"id":"threatmodel","g":"sec","word":"Samhaltú bagairtí","text":"Machnamh ar cé a d'fhéadfadh ionsaí a dhéanamh, conas, agus cad a dhéanfá chun é a chosc.","also":["samhail bagairtí","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Sárú sonraí","text":"Nuair a fhaigheann daoine neamhúdaraithe faisnéis phríobháideach, nó nuair a chailltear nó a athraítear í gan chead.","also":["sáruithe sonraí","data breaches"]},{"id":"pii","g":"sec","word":"Sonraí pearsanta","text":"Faisnéis ar bith faoi dhuine inaitheanta, mar ainm, seoladh ríomhphoist nó suíomh. Tugtar PII uirthi freisin.","also":["PII","faisnéis inaitheanta phearsanta","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"An dlí Eorpach ar shonraí pearsanta (tá a leagan féin ag an Ríocht Aontaithe): ná bailigh ach a bhfuil gá leis, coinnigh slán é agus lig do dhaoine a gcuid sonraí féin a fheiceáil nó a scriosadh.","also":["An Rialachán Ginearálta maidir le Cosaint Sonraí","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Cosaint sonraí","text":"Aire cheart a thabhairt do shonraí pearsanta de réir an dlí.","also":["dlí cosanta sonraí","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Beartas príobháideachais","text":"Leathanach poiblí a deir cé na sonraí pearsanta a bhailíonn tú, cén fáth agus cad a dhéanann tú leo.","also":["ráiteas príobháideachais","fógra príobháideachais","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Toiliú","text":"Cead soiléir saor ó dhuine chun a shonraí a úsáid ar bhealach áirithe. Is féidir leis é a tharraingt siar am ar bith.","also":["rogha dheonach","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Fianán","text":"Comhad beag a shábhálann suíomh i do bhrabhsálaí chun rudaí a mheabhrú, mar logáil isteach. Teastaíonn do thoiliú roimh ré do chuid acu.","also":["fianáin","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Íoslaghdú sonraí","text":"Gan ach na sonraí pearsanta atá de dhíth don jab a bhailiú agus a choinneáil.","also":["íoslaghdú sonraí","data minimization"]},{"id":"retention","g":"sec","word":"Coinneáil sonraí","text":"An fad a choinnítear sonraí sula scriostar iad. Tá sé níos sábháilte, agus de réir an dlí go minic, gan iad a choinneáil níos faide ná mar is gá.","also":["tréimhse choinneála","retention period"]},{"id":"anon","g":"sec","word":"Anaithnidiú","text":"Sonraí a athrú ionas nach féidir duine ar bith a aithint go réasúnta astu a thuilleadh.","also":["anaithnidithe","sonraí anaithnide","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Ainm bréige a chur in ionad ainm","text":"Cóid a chur in áit ainmneacha agus sonraí eile, le heochair ar leith chun iad a nascadh ar ais. Is sonraí pearsanta fós iad.","also":["faoi ainm bréige","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Comhaontú próiseála sonraí (DPA)","text":"Conradh a shocraíonn conas is féidir le soláthraí sonraí pearsanta a láimhseáil ar do shon.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Measúnú tionchair ar chosaint sonraí (DPIA)","text":"Súil chúramach, sula dtosaíonn tú, ar an tionchar a d'fhéadfadh plean úsáide sonraí pearsanta a imirt ar dhaoine agus conas na rioscaí a laghdú.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Loga iniúchta","text":"Taifead ar cé a rinne cad agus cathain, chun gníomhartha a sheiceáil níos déanaí.","also":["logaí iniúchta","rian iniúchta","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Comhlíonadh","text":"Na dlíthe, rialacha agus caighdeáin a bhaineann leat a leanúint, agus a bheith in ann sin a léiriú.","also":["comhlíontach","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Caighdeán idirnáisiúnta aitheanta chun slándáil faisnéise a bhainistiú. Is féidir cuideachtaí a dheimhniú dá réir.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Tuairisc Mheiriceánach, seiceáilte ag iniúchóirí seachtracha, a léiríonn go dtugann cuideachta aire cheart do shonraí custaiméirí.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI a oibríonn ar thasc leis féin: léann sé an cód, déanann sé athruithe, ritheann sé seiceálacha agus tuairiscíonn sé ar ais. Seiceáiltear a chuid oibre fós.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Na blúirí beaga téacs a léann agus a scríobhann AI, thart ar thrí cheathrú d’fhocal an ceann. Áirítear úsáid AI i tokens, mar sin fágann níos lú tokens níos mó de do phlean.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Ordú beag a ritheann leis féin ag nóiméad socraithe, mar shampla nuair a thosaíonn seisiún AI, ionas go gcloiseann an fhoireann do chuid tráchtanna.","also":["hooks"]},{"id":"ai","g":"ai","word":"Intleacht shaorga (AI)","text":"Córais ríomhaireachta a dhéanann rudaí a shamhlaímid le daoine de ghnáth, mar scríobh, ceisteanna a fhreagairt nó pictiúir a aithint.","also":["AI","IS","intleacht shaorga","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Meaisínfhoghlaim (ML)","text":"Modh a ligeann do ríomhairí patrúin a fhoghlaim ó go leor samplaí seachas rialacha beachta a thabhairt dóibh.","also":["meaisínfhoghlaim","machine learning"]},{"id":"model","g":"ai","word":"Samhail","text":"“Inchinn” oilte córais AI, a tógadh trí fhoghlaim ó líon ollmhór samplaí. Bíonn scil, luas agus praghas difriúil ag samhlacha éagsúla.","also":["samhlacha","samhail AI","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Samhail mhór teanga (LLM)","text":"Samhail AI a oiltear ar mhéid ollmhór téacs, ionas gur féidir léi teanga a léamh agus a scríobh.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"AI giniúnach","text":"AI a chruthaíonn rudaí nua, mar théacs, pictiúir nó cód, seachas iad a shórtáil nó a aithint amháin.","also":["GenAI","intleacht shaorga ghiniúnach"]},{"id":"chatbot","g":"ai","word":"Comhrá-róbat","text":"Clár a labhraíonn tú leis i ngnáth-theanga, trí chlóscríobh nó trí chaint.","also":["comhrá-róbait","chatbots"]},{"id":"prompt","g":"ai","word":"Leid","text":"An méid a thugann tú do AI: do cheist nó do threoracha, agus aon rud eile a thugann tú dó. Is gnách go bhfaigheann leideanna níos soiléire freagraí níos fearr.","also":["leideanna","prompts"]},{"id":"prompteng","g":"ai","word":"Innealtóireacht leideanna","text":"An scil leideanna a scríobh a thugann torthaí iontaofa úsáideacha.","also":["leideanna a scríobh"]},{"id":"sysprompt","g":"ai","word":"Leid chórais","text":"Treoracha cúlra a fhaigheann AI sula dtosaíonn an comhrá, a shocraíonn a ról agus a rialacha. Bíonn níos mó meáchain acu ná an méid a chlóscríobhann tú.","also":["leideanna córais","treoir chórais","treoracha córais","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Comhthéacs","text":"Gach rud a fheiceann an AI agus é ag obair: na treoracha, do theachtaireachtaí, comhaid atá léite aige agus freagraí roimhe seo.","noTip":1},{"id":"ctxwin","g":"ai","word":"Fuinneog chomhthéacs","text":"An méid is féidir le AI a choinneáil i gcuimhne ag an am céanna, tomhaiste i tokens. Thar sin, baintear na seanchodanna nó déantar achoimre orthu.","also":["fuinneoga comhthéacs","context windows"]},{"id":"session","g":"ai","word":"Seisiún","text":"Comhrá oibre amháin le AI, ó thús go deireadh. Tosaíonn seisiún nua le cuimhne úr.","also":["seisiúin","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Cuimhne","text":"Nótaí a choinníonn AI idir seisiúin, ionas go gcuimhníonn sé ar do roghanna agus ar chinntí a rinneadh roimhe seo.","noTip":1},{"id":"hallucination","g":"ai","word":"Siabhránacht","text":"Nuair a deir AI rud go muiníneach atá cumtha nó mícheart. Seiceáil fíricí tábhachtacha.","also":["siabhránachtaí","siabhránú","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Oiliúint","text":"Samhail a mhúineadh le líon ollmhór samplaí sula n-úsáideann aon duine í.","also":["oilte","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Sonraí oiliúna","text":"Na samplaí ar fhoghlaim samhail uathu. Stopann a heolas ag an dáta a bailíodh na sonraí sin.","also":["tacar oiliúna","training set"]},{"id":"cutoff","g":"ai","word":"Teorainn ama eolais","text":"An dáta a stopann an t-eolas atá ionsuite in AI. Ní bheidh eolas aige ar rudaí níos déanaí mura gcuardaíonn sé iad.","also":["teorainn ama oiliúna","training cutoff"]},{"id":"finetune","g":"ai","word":"Mionchoigeartú","text":"Oiliúint bhreise ar shamhail atá ann cheana le do shamplaí féin, chun í a fheabhsú ag jab áirithe.","also":["mionchoigeartaigh","mionchoigeartaithe","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Tátal","text":"Samhail AI á húsáid i ndáiríre chun freagra a thabhairt, seachas í a bheith á hoiliúint.","also":["tátal samhla","model inference"]},{"id":"tooluse","g":"ai","word":"Úsáid uirlisí","text":"AI atá in ann rudaí a dhéanamh, ní caint amháin: orduithe a rith, comhaid a léamh nó an gréasán a chuardach, trí uirlisí a thugann an aip dó.","also":["glaoch uirlise","glaonna uirlisí","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Fo-ghníomhaire","text":"Cabhróir AI a fhaigheann jab níos lú ó phríomh-AI agus a thugann an toradh ar ais dó.","also":["fo-ghníomhairí","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Ilghníomhaireach (multi-agent)","text":"Roinnt AI ag obair le chéile ar phíosa oibre amháin, a chuid féin ag gach ceann acu, mar fhoireann bheag.","also":["córas ilghníomhaireach","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Féinriail","text":"An méid is féidir le AI a dhéanamh as a stuaim féin sula gcaithfidh sé ceist a chur ar dhuine.","also":["féinrialaitheach","autonomous"]},{"id":"hitl","g":"ai","word":"Duine sa lúb","text":"Duine a choinneáil páirteach chun obair an AI a sheiceáil nó a cheadú ag pointí tábhachtacha. In AI-gile, is tusa é sin.","also":["duine sa lúb","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Srianta sábháilteachta","text":"Teorainneacha agus seiceálacha a choinníonn gníomhartha AI sábháilte, mar shampla cead a bheith ag teastáil sula dtéann rud ar bith beo. Laghdaíonn siad an baol botún, ach ní chuireann siad deireadh leo.","also":["srian sábháilteachta","guardrail"]},{"id":"rag","g":"ai","word":"Giniúint le haisghabháil (RAG)","text":"Ligean do AI cuardach a dhéanamh i do cháipéisí féin sula bhfreagraíonn sé, ionas go mbeidh a chuid freagraí bunaithe ar do chuid fíricí.","also":["RAG","giniúint le haisghabháil","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Leabú","text":"Téacs a athrú ina liosta uimhreacha a léiríonn a bhrí, ionas gur féidir le ríomhaire rudaí a bhfuil brí cosúil leo a aimsiú.","also":["leabuithe","embeddings"]},{"id":"vectordb","g":"ai","word":"Bunachar veicteoirí","text":"Bunachar a chuardaíonn na liostaí uimhreacha sin (leabuithe) chun ábhar le brí cosúil leis a aimsiú.","also":["bunachair veicteoirí","stór veicteoirí","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Bealach coitianta chun uirlisí agus foinsí sonraí a cheangal le haipeanna AI, ionas gur féidir leis an AI iad a úsáid.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Teocht","text":"Socrú a shocraíonn cé chomh dána is atá freagraí AI. Tugann leibhéal íseal freagraí níos seasta agus níos intuartha; tugann leibhéal ard freagraí níos éagsúla. Ní chinntíonn ceachtar acu go mbeidh sé ceart i gcónaí.","also":["teocht samhla","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Ilmhódach","text":"In ann oibriú le níos mó ná cineál amháin faisnéise, mar théacs, pictiúir agus fuaim.","also":["ilmhódach","multi-modal"]},{"id":"evals","g":"ai","word":"Meastóireacht (eval)","text":"Tástáil phleanáilte ar chomh maith is a éiríonn le AI ar shamplaí roghnaithe, ionas gur féidir samhlacha nó leideanna a chur i gcomparáid.","also":["eval","evals","meastóireachtaí"]},{"id":"bias","g":"ai","word":"Claonadh","text":"Nuair a chlaonann AI, nó duine, go héagórach i dtreo amháin, go minic mar gheall ar an ábhar ar fhoghlaim sé uaidh.","also":["claonta","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI freagrach","text":"AI a úsáid go cothrom, go sábháilte agus go macánta, agus daoine fós freagrach as na torthaí.","also":["AI eiticiúil","ethical AI","responsible AI"]},{"id":"injection","g":"ai","word":"Instealladh leideanna","text":"Cleas ina ndéanann treoracha folaithe i leathanach gréasáin nó i gcomhad iarracht ar AI a chur ag déanamh ruda nár iarr a úsáideoir.","also":["instealltaí leideanna","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Teorainn ráta","text":"Uasmhéid iarratas is féidir a sheoladh chuig seirbhís i dtréimhse áirithe. Má sháraíonn tú é, caithfidh tú fanacht.","also":["teorainneacha ráta","ráta teoranta","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Teorainn úsáide","text":"An méid oibre AI a cheadaíonn do phlean i dtréimhse; ina dhiaidh sin, cuirtear ar sos í nó cosnaíonn sí níos mó.","also":["teorainneacha úsáide","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Bogearraí a thógáil go príomha trí chur síos a dhéanamh do AI ar a bhfuil uait agus ligean dó an cód a scríobh.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Buiséad","text":"An méid airgid atá curtha ar leataobh do rud.","also":["buiséid","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Meastachán costais","text":"An tuairim is fearr ar chostas ruda sula dtosaíonn tú.","also":["meastacháin costais","cost estimates"]},{"id":"roi","g":"money","word":"Toradh ar infheistíocht (ROI)","text":"An méid a fhaigheann tú ar ais i gcomparáid leis an méid a chuir tú isteach. Má tá sé dearfach, b'fhiú é.","also":["ROI"]},{"id":"tco","g":"money","word":"Costas iomlán úinéireachta (TCO)","text":"Gach costas thar shaolré ruda, ní an praghas ceannaigh amháin: reáchtáil, tacaíocht, uasghráduithe agus scor sa deireadh.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx agus OpEx","text":"Is éard is CapEx ann airgead a chaitear roimh ré ar rudaí a choinníonn tú; is éard is OpEx ann caiteachas leanúnach, mar bhillí míosúla.","also":["CapEx","OpEx","caiteachas caipitil","caiteachas oibriúcháin","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Síntiús","text":"Íocaíocht rialta, go minic gach mí nó gach bliain, chun leanúint de rud a úsáid.","also":["síntiúis","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Bogearraí mar sheirbhís (SaaS)","text":"Bogearraí a úsáideann tú ar líne agus a íocann tú astu le síntiús, agus an déantóir á reáchtáil duit.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Íoc de réir úsáide","text":"Gan íoc ach as an méid a úsáideann tú, mar shampla le néalríomhaireacht nó le tokens AI.","also":["pay as you go","pay-as-you-go","praghsáil bunaithe ar úsáid","usage-based pricing"]},{"id":"overage","g":"money","word":"Barrachas úsáide","text":"Úsáid os cionn an mhéid atá i do phlean, rud a bhféadfadh costas breise a bheith air.","also":["overage","overages","overage charges","táillí barrachais"]},{"id":"billingalert","g":"money","word":"Foláireamh billeála","text":"Teachtaireacht nuair a shroicheann caiteachas nó úsáid leibhéal a roghnaigh tú. Cuireann sé ar an eolas thú, ach ní stopann sé táillí breise i gcónaí.","also":["billing alert","billing alerts","foláirimh billeála","foláireamh caiteachais","spending alert"]},{"id":"freetier","g":"money","word":"Leibhéal saor in aisce","text":"Leibhéal saor in aisce de sheirbhís íoctha, le teorainneacha. Úsáideach chun tosú.","also":["free tier","free plan","plean saor in aisce"]},{"id":"pricing","g":"money","word":"Plean praghsála","text":"Na pacáistí éagsúla a dhíolann seirbhís, gach ceann acu lena phraghas agus lena theorainneacha féin.","also":["pricing plan","pricing plans","pleananna praghsála","price plan"]},{"id":"licence","g":"money","word":"Ceadúnas","text":"Na rialacha maidir leis an gcaoi a bhféadfaidh tú rud a rinne duine eile a úsáid, a chóipeáil, a athrú nó a roinnt, mar shampla bogearraí, clófhoirne nó pictiúir.","also":["ceadúnais","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Foinse oscailte","text":"Bogearraí a bhféadfaidh aon duine a gcód a léamh, a úsáid agus a athrú go minic, saor in aisce, faoi rialacha a gceadúnais.","also":["open source","open-source","bogearraí foinse oscailte","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Ceadúnas foinse oscailte","text":"Na rialacha a ghabhann le cód foinse oscailte. Ligeann cuid acu duit beagnach aon rud a dhéanamh (cosúil le MIT); iarrann cuid eile ort do chuid athruithe a roinnt freisin (cosúil le GPL).","also":["ceadúnais foinse oscailte","open source licence","open source licences","MIT licence","ceadúnas MIT","GPL"]},{"id":"proprietary","g":"money","word":"Dílseánach","text":"I seilbh cuideachta agus gan a bheith saor le cóipeáil ná le hathrú. A mhalairt d'fhoinse oscailte.","also":["proprietary","bogearraí dílseánacha","proprietary software"]},{"id":"copyright","g":"money","word":"Cóipcheart","text":"Ceart dlíthiúil cruthaitheora smacht a choinneáil ar chóipeanna dá shaothar, cód agus scríbhneoireacht san áireamh.","also":["copyright","copyrighted","faoi chóipcheart"],"noTip":1},{"id":"ip","g":"money","word":"Maoin intleachtúil (IP)","text":"Smaointe agus cruthúcháin a mheasann an dlí a bheith faoi úinéireacht, mar shampla cód, dearaí, ainmneacha agus lógónna.","also":["IP","intellectual property","maoin intleachtúil"]},{"id":"tos","g":"money","word":"Téarmaí seirbhíse","text":"Na rialacha a aontaíonn tú leo nuair a úsáideann tú seirbhís.","also":["terms of service","téarmaí agus coinníollacha","terms and conditions","téarmaí úsáide","terms of use"]},{"id":"contract","g":"money","word":"Conradh","text":"Comhaontú scríofa idir dhá thaobh a thacóidh an dlí leis.","also":["conarthaí","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Ráiteas oibre (SOW)","text":"Doiciméad a leagann amach go beacht cén obair a dhéanfar, faoi cén dáta agus ar cén phraghas.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Praghas seasta","text":"Praghas comhaontaithe don jab ar fad, is cuma cé chomh fada is a thógann sé.","also":["fixed price","fixed-price","praghas socraithe"]},{"id":"tm","g":"money","word":"Am agus ábhair","text":"Íoc as na huaireanta a oibríodh i ndáiríre agus as na rudaí a úsáideadh i ndáiríre, seachas praghas socraithe.","also":["T&M","time and materials"]},{"id":"invoice","g":"money","word":"Sonraisc","text":"Bille a iarrann íocaíocht as obair a rinneadh nó as earraí a soláthraíodh.","also":["sonraiscí","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Faoi ghlas ag soláthraí","text":"Nuair a bhíonn sé chomh deacair nó chomh costasach sin imeacht ó sholáthraí go bhfuil tú sáinnithe leis.","also":["vendor lock-in","lock-in","lockin"]},{"id":"procurement","g":"money","word":"Soláthar","text":"An próiseas chun soláthraithe a roghnú agus ceannach uathu.","also":["procurement","ceannach"]},{"id":"servicecredit","g":"money","word":"Creidmheas seirbhíse","text":"Airgead ar ais nó lascaine a gheobhaidh tú nuair a theipeann ar sholáthraí a SLA a chomhlíonadh.","also":["creidmheasanna seirbhíse","service credit","service credits"]}]}};
